1	// Spike 01 — S-01: PTY-host the real claude CLI under ConPTY.
2	// Throwaway harness. Findings: spike/findings/s-01-pty-host.md
3	const { app, BrowserWindow, ipcMain, Menu } = require('electron');
4	const pty = require('node-pty');
5	const path = require('path');
6	const fs = require('fs');
7	
8	const SMOKE = process.argv.includes('--smoke');
9	const SMOKE_SECONDS = 20;
10	
11	// cwd for the hosted session: SPIKE_CWD env wins, else a scratch test project.
12	function resolveSessionCwd() {
13	  if (process.env.SPIKE_CWD) return process.env.SPIKE_CWD;
14	  const dir = path.resolve(__dirname, '..', '.claude', 'work_files', 'test-project');
15	  fs.mkdirSync(dir, { recursive: true });
16	  const readme = path.join(dir, 'README.md');
17	  if (!fs.existsSync(readme)) {
18	    fs.writeFileSync(readme, '# spike test project\n\nScratch project for the S-01 PTY harness.\n');
19	  }
20	  return dir;
21	}
22	
23	// Spawn strategy probe (a finding in itself): try the npm .cmd shim directly,
24	// fall back to cmd.exe /c. CLAUDE_CMD env overrides everything.
25	function spawnClaude(cols, rows, cwd) {
26	  const opts = {
27	    name: 'xterm-256color',
28	    cols,
29	    rows,
30	    cwd,
31	    env: process.env,
32	    useConpty: true,
33	  };
34	  const attempts = process.env.CLAUDE_CMD
35	    ? [{ label: 'CLAUDE_CMD override', file: process.env.CLAUDE_CMD, args: [] }]
36	    : [
37	        { label: 'direct claude.cmd', file: 'claude.cmd', args: [] },
38	        { label: 'cmd.exe /c claude', file: 'cmd.exe', args: ['/c', 'claude'] },
39	      ];
40	  for (const a of attempts) {
41	    try {
42	      const p = pty.spawn(a.file, a.args, opts);
43	      console.log(`[spike] spawn OK via: ${a.label} (pid ${p.pid})`);
44	      return p;
45	    } catch (err) {
46	      console.log(`[spike] spawn FAILED via: ${a.label} — ${err.message}`);
47	    }
48	  }
49	  throw new Error('all spawn strategies failed');
50	}
51	
52	function runSmoke() {
53	  // No window: just prove ConPTY spawn + output flow, then exit.
54	  // A child that exits during the smoke window is a FAIL — e.g. the cmd.exe
55	  // fallback "spawns OK" and prints an error even when claude isn't on PATH.
56	  const cwd = resolveSessionCwd();
57	  console.log(`[smoke] cwd=${cwd}`);
58	  let bytes = 0;
59	  let chunks = 0;
60	  let firstByteMs = -1;
61	  let head = '';
62	  let exited = null;
63	  let done = false;
64	  const t0 = Date.now();
65	  let child;
66	  try {
67	    child = spawnClaude(120, 30, cwd);
68	  } catch (err) {
69	    console.error(`[smoke] FAIL: ${err.message}`);
70	    app.exit(1);
71	    return;
72	  }
73	  const finish = () => {
74	    if (done) return;
75	    done = true;
76	    clearTimeout(timer);
77	    console.log(`[smoke] first output after ${firstByteMs} ms; ${bytes} bytes in ${chunks} chunks`);
78	    if (head) console.log(`[smoke] output head: ${JSON.stringify(head.slice(0, 200))}`);
79	    if (exited) console.log(`[smoke] child exited during smoke window (code ${exited.exitCode})`);
80	    const ok = firstByteMs >= 0 && bytes > 0 && !exited;
81	    console.log(ok ? '[smoke] PASS' : '[smoke] FAIL');
82	    try { child.kill(); } catch (_) {}
83	    app.exit(ok ? 0 : 1);
84	  };
85	  child.onData((d) => {
86	    if (firstByteMs < 0) firstByteMs = Date.now() - t0;
87	    bytes += Buffer.byteLength(d, 'utf8');
88	    chunks += 1;
89	    if (head.length < 200) head += d;
90	  });
91	  child.onExit(({ exitCode }) => { exited = { exitCode }; finish(); });
92	  const timer = setTimeout(finish, SMOKE_SECONDS * 1000);
93	}
94	
95	function runWindow() {
96	  const cwd = resolveSessionCwd();
97	  // No menu: the default one ships Ctrl+R reload, which blanks the xterm and
98	  // desyncs it from the live PTY — indistinguishable from real TUI corruption.
99	  Menu.setApplicationMenu(null);
100	  const win = new BrowserWindow({
101	    width: 1100,
102	    height: 750,
103	    backgroundColor: '#1e1e1e',
104	    webPreferences: { preload: path.join(__dirname, 'preload.js') },
105	  });
106	
107	  let child = null;
108	
109	  // Renderer announces its initial size; spawn then so cols/rows match.
110	  ipcMain.once('pty:ready', (_e, { cols, rows }) => {
111	    child = spawnClaude(cols, rows, cwd);
112	    child.onData((d) => {
113	      if (!win.isDestroyed()) win.webContents.send('pty:data', d);
114	    });
115	    child.onExit(({ exitCode }) => {
116	      child = null; // dead PTY: writes after exit would raise async socket errors
117	      if (!win.isDestroyed()) {
118	        win.webContents.send('pty:data', `\r\n[spike] claude exited (code ${exitCode})\r\n`);
119	      }
120	    });
121	  });
122	
123	  ipcMain.on('pty:input', (_e, data) => {
124	    if (child) { try { child.write(data); } catch (_) {} }
125	  });
126	  ipcMain.on('pty:resize', (_e, { cols, rows }) => {
127	    if (child && cols > 0 && rows > 0) { try { child.resize(cols, rows); } catch (_) {} }
128	  });
129	
130	  win.on('closed', () => { if (child) { try { child.kill(); } catch (_) {} } });
131	
132	  // Surface renderer console on stdout (headless-ish debugging of the
133	  // harness). Electron ≥32 passes a details object; older passed positionals.
134	  win.webContents.on('console-message', (evt, level, message) => {
135	    const msg = message !== undefined ? message : evt.message;
136	    const lvl = message !== undefined ? level : evt.level;
137	    console.log(`[renderer:${lvl}] ${msg}`);
138	  });
139	
140	  // SPIKE_AUTOCLOSE=<seconds>: self-close for scripted checks.
141	  const autoclose = Number(process.env.SPIKE_AUTOCLOSE);
142	  if (Number.isFinite(autoclose) && autoclose > 0) {
143	    setTimeout(() => { if (!win.isDestroyed()) win.close(); }, autoclose * 1000);
144	  }
145	
146	  win.loadFile(path.join(__dirname, 'renderer', 'index.html'));
147	  win.webContents.on('did-finish-load', () => {
148	    win.setTitle(`spike S-01 — claude @ ${cwd}`);
149	  });
150	}
151	
152	app.whenReady().then(() => (SMOKE ? runSmoke() : runWindow()));
153	app.on('window-all-closed', () => app.quit());
154

