// S-03: HookListener stand-in. Loopback-only HTTP server implementing the
// §5.29 floor: Host-header allowlist AND per-session token, both always.
// Scenario-driven auto-decider simulates the human: respond <decision> after
// <delayMs>, or never ('hang').
//
//   node listener.js <outDir> <decision: allow|deny|ask|hang> [delayMs]
//
// Writes <outDir>/listener.json {port, token, pid} for the settings generator,
// and appends a timestamped audit trail to <outDir>/listener.log.
const http = require('http');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const OUT = process.argv[2];
const DECISION = process.argv[3] || 'allow';
const DELAY = Number(process.argv[4] || 0);
if (!OUT) { console.error('usage: node listener.js <outDir> <decision> [delayMs]'); process.exit(1); }
fs.mkdirSync(OUT, { recursive: true });

const token = crypto.randomBytes(16).toString('hex');
const log = (line) =>
  fs.appendFileSync(path.join(OUT, 'listener.log'), `${new Date().toISOString()} ${line}\n`);

const server = http.createServer((req, res) => {
  const host = (req.headers.host || '').split(':')[0];
  if (host !== '127.0.0.1' && host !== 'localhost') {
    log(`REJECT bad-host host=${req.headers.host}`);
    res.writeHead(403); return res.end();
  }
  if (req.headers['x-s03-token'] !== token) {
    log('REJECT bad-token');
    res.writeHead(401); return res.end();
  }
  let body = '';
  req.on('data', (c) => (body += c));
  req.on('end', () => {
    let evt = {};
    try { evt = JSON.parse(body); } catch (_) {}
    log(`REQUEST event=${evt.hook_event_name} tool=${evt.tool_name} session=${evt.session_id} ` +
        `input=${JSON.stringify(evt.tool_input || {}).slice(0, 160)}`);
    if (DECISION === 'hang') { log('HANG — never responding (timeout probe)'); return; }
    setTimeout(() => {
      const reason =
        DECISION === 'deny'
          ? 'S03-DENY-REASON: switchboard operator rejected this edit'
          : `S03 auto-${DECISION}`;
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ decision: DECISION, reason }));
      log(`RESPONDED ${DECISION} after ${DELAY}ms hold`);
    }, DELAY);
  });
});

server.listen(0, '127.0.0.1', () => {
  const { port } = server.address();
  fs.writeFileSync(
    path.join(OUT, 'listener.json'),
    JSON.stringify({ port, token, pid: process.pid, decision: DECISION, delayMs: DELAY })
  );
  log(`LISTENING port=${port} decision=${DECISION} delay=${DELAY}ms`);
  console.log(`listening on 127.0.0.1:${port}`);
});

// S-03: the PreToolUse hook command. Forwards the hook JSON from stdin to the
// listener, blocks until the "human" decision arrives, then emits Claude
// Code's hook-output JSON. Listener unreachable => fail-open (exit 0, no
// output => CLI default behavior), logged.
//
//   node hook-forward.js <port> <token> <logfile>
const fs = require('fs');
const http = require('http');

const [, , port, token, logfile] = process.argv;
const mark = (s) => {
  try { fs.appendFileSync(logfile, `${new Date().toISOString()} ${s}\n`); } catch (_) {}
};

const stdin = fs.readFileSync(0, 'utf8');
const t0 = Date.now();
mark(`hook invoked pid=${process.pid}`);

const req = http.request(
  {
    host: '127.0.0.1',
    port,
    path: '/pretooluse',
    method: 'POST',
    headers: { 'content-type': 'application/json', 'x-s03-token': token },
  },
  (res) => {
    let body = '';
    res.on('data', (c) => (body += c));
    res.on('end', () => {
      let d = {};
      try { d = JSON.parse(body); } catch (_) {}
      const decision = ['allow', 'deny', 'ask'].includes(d.decision) ? d.decision : null;
      mark(`decision=${d.decision || 'invalid'} roundtrip=${Date.now() - t0}ms`);
      if (decision) {
        process.stdout.write(
          JSON.stringify({
            hookSpecificOutput: {
              hookEventName: 'PreToolUse',
              permissionDecision: decision,
              permissionDecisionReason: d.reason || '',
            },
          })
        );
      }
      process.exit(0);
    });
  }
);
req.on('error', (e) => {
  mark(`listener unreachable (${e.message}) — fail-open, no output`);
  process.exit(0);
});
req.end(stdin);
// If the listener hangs, this process hangs with it — the CLI's own hook
// timeout is then the thing being measured.

// S-03 interactive driver: scripts a REAL interactive claude TUI session under
// ConPTY to observe permission-prompt behavior. Must run with Electron's ABI
// (node-pty was rebuilt for it):
//   ELECTRON_RUN_AS_NODE=1 <spike>/node_modules/electron/dist/electron.exe pty-drive.js \
//     <scenario: ask|hang> <settings-file-mixed-path> <fixture-cwd> <outDir>
//
// ask:  listener answers "ask" -> expect the TUI permission prompt; capture its
//       full option text (don't-ask-again evidence), accept, verify the write.
// hang: listener never answers -> does the TUI permission prompt still engage
//       (fallback) after the hook times out, and how long does that take?
const pty = require('node-pty');
const fs = require('fs');
const path = require('path');

const [, , scenario, settingsFile, fixtureCwd, outDir] = process.argv;
if (!outDir) { console.error('usage: pty-drive.js <ask|hang> <settings> <cwd> <outDir>'); process.exit(1); }
fs.mkdirSync(outDir, { recursive: true });

const t0 = Date.now();
const rawPath = path.join(outDir, 'raw.log');
const evPath = path.join(outDir, 'events.log');
const ev = (s) => {
  const line = `+${String(Date.now() - t0).padStart(6)}ms ${s}`;
  fs.appendFileSync(evPath, line + '\n');
  console.log(line);
};

const strip = (s) =>
  s
    .replace(/\x1b\][^\x07\x1b]*(\x07|\x1b\\)/g, '') // OSC
    .replace(/\x1b\[[0-9;?]*[ -/]*[@-~]/g, '')       // CSI
    .replace(/\x1b[=>NOM78]/g, '')
    .replace(/[\x00-\x08\x0b-\x1f]/g, '');

const env = { ...process.env };
delete env.ELECTRON_RUN_AS_NODE; // S-01 landmine: don't leak into children

const child = pty.spawn('claude.cmd', ['--settings', settingsFile], {
  name: 'xterm-256color', cols: 120, rows: 32, cwd: fixtureCwd, env, useConpty: true,
});
ev(`spawned pid=${child.pid} scenario=${scenario}`);

let stripped = '';
let consumed = 0; // strip() index up to which matches were already handled
child.onData((d) => {
  fs.appendFileSync(rawPath, d);
  stripped += strip(d);
});
child.onExit(({ exitCode }) => { ev(`child exit code=${exitCode}`); finish(); });

const result = { scenario, steps: [], promptCapture: null, promptLatencyMs: null, fileWritten: null };
let finished = false;
function finish(fail) {
  if (finished) return;
  finished = true;
  const probe = path.join(fixtureCwd, `live-${scenario}.txt`);
  result.fileWritten = fs.existsSync(probe);
  if (result.fileWritten) result.fileContent = fs.readFileSync(probe, 'utf8');
  result.failed = !!fail;
  fs.writeFileSync(path.join(outDir, 'result.json'), JSON.stringify(result, null, 2));
  ev(`DONE fileWritten=${result.fileWritten} failed=${!!fail}`);
  try { child.kill(); } catch (_) {}
  setTimeout(() => process.exit(fail ? 1 : 0), 500);
}

// Sequential step engine: each step waits for a regex in NEW stripped output.
const steps = [];
let stepIdx = 0;
let stepStart = Date.now();
function runStep() {
  const s = steps[stepIdx];
  if (!s) return finish(false);
  const iv = setInterval(() => {
    const tail = stripped.slice(consumed);
    const m = tail.match(s.match);
    if (m) {
      clearInterval(iv);
      const at = Date.now() - t0;
      ev(`step "${s.name}" matched ${JSON.stringify(m[0].slice(0, 60))}`);
      result.steps.push({ name: s.name, atMs: at, sinceStepStartMs: Date.now() - stepStart });
      if (s.capture) {
        const ctx = tail.slice(Math.max(0, m.index - 200), m.index + 1400);
        result.promptCapture = ctx;
        fs.writeFileSync(path.join(outDir, 'prompt-capture.txt'), ctx);
      }
      if (s.latency) result.promptLatencyMs = Date.now() - s.latencyFrom();
      consumed += m.index + m[0].length;
      const proceed = () => { stepIdx++; stepStart = Date.now(); runStep(); };
      if (s.send !== undefined) setTimeout(() => { child.write(s.send); proceed(); }, s.sendDelayMs || 400);
      else proceed();
    } else if (Date.now() - stepStart > s.timeoutMs) {
      clearInterval(iv);
      ev(`step "${s.name}" TIMED OUT after ${s.timeoutMs}ms`);
      result.steps.push({ name: s.name, timedOut: true });
      fs.writeFileSync(path.join(outDir, 'timeout-tail.txt'), stripped.slice(-3000));
      if (s.optional) { stepIdx++; stepStart = Date.now(); runStep(); }
      else finish(true);
    }
  }, 150);
}

let promptSentAt = Date.now();
const PERM_RE = /(Do you want|Allow this|Yes, (and )?(allow|don'?t ask)|don'?t ask again|Permission)/i;

steps.push(
  // Trust prompt may or may not appear; accept if it does.
  { name: 'trust-or-ready', match: /(Do you trust the files|\? for shortcuts)/i, timeoutMs: 60000,
    send: undefined },
  { name: 'ready', match: /\? for shortcuts/i, timeoutMs: 60000, optional: true },
  { name: 'send-prompt', match: /[\s\S]/, timeoutMs: 5000,
    send: `Use the Write tool to create the file live-${scenario}.txt containing exactly: hello-${scenario}\r`,
    sendDelayMs: 1200 },
  { name: 'permission-prompt', match: PERM_RE,
    timeoutMs: scenario === 'hang' ? 240000 : 90000,
    capture: true, latency: true, latencyFrom: () => promptSentAt,
    // settle before answering so the full option list is in the capture buffer
    send: '\r', sendDelayMs: 2500 },
  { name: 'write-done', match: new RegExp(`live-${scenario}\\.txt|hello-${scenario}`, 'i'),
    timeoutMs: 90000, optional: true },
  { name: 'exit', match: /[\s\S]/, timeoutMs: 3000, send: '/exit\r', sendDelayMs: 1500 },
  { name: 'gone', match: /(^|\s)$/, timeoutMs: 15000, optional: true }
);

// Mark when the edit request actually went in (for prompt latency).
const origWrite = child.write.bind(child);
child.write = (data) => {
  if (typeof data === 'string' && data.includes('Use the Write tool')) promptSentAt = Date.now();
  return origWrite(data);
};

// Special-case the trust prompt: if the first match was trust, answer it.
const firstStep = steps[0];
firstStep.send = undefined; // decided dynamically below
const origRunStep = runStep;
// Simpler: wrap — after step 0 matches, if it was the trust prompt, press Enter.
steps[0] = {
  ...firstStep,
  send: undefined,
};
// Replace engine start with a dynamic responder for step 0.
const iv0 = setInterval(() => {
  const m = stripped.match(/(Do you trust the files|\? for shortcuts)/i);
  if (!m) {
    if (Date.now() - t0 > 60000) { clearInterval(iv0); ev('startup TIMED OUT'); finish(true); }
    return;
  }
  clearInterval(iv0);
  ev(`startup matched: ${JSON.stringify(m[0])}`);
  result.steps.push({ name: 'startup', atMs: Date.now() - t0, matched: m[0] });
  if (/trust/i.test(m[0])) {
    setTimeout(() => child.write('\r'), 600); // accept trust; ready check comes next
  }
  consumed = stripped.indexOf(m[0]) + m[0].length;
  stepIdx = 1; stepStart = Date.now();
  runStep();
}, 150);

// Global safety net.
setTimeout(() => { ev('GLOBAL TIMEOUT'); finish(true); }, 420000);

