// S-04: transcript discovery + live tailing, transcript-only (no hooks).
//   node tail-transcript.js <session-cwd-mixed> <outDir> [--follow-ms N]
//
// Discovery: snapshot ~/.claude/projects/* before the session starts, then
// poll for a NEW .jsonl anywhere under it; record which project dir it landed
// in and how that dir name maps to the session cwd (the slug question).
//
// Tailing: byte-offset polling every 100ms (fs.watch is unreliable on
// Windows); split on \n; per-line tolerant parse — a malformed line increments
// a counter and never throws.
//
// Derived live state (printed as a status line, transcript-only):
//   status: working | awaiting-input | done (heuristic from last entry)
//   tokens: running totals from message.usage
//   tools:  count + last tool + files touched
//   lag:    entry.timestamp vs wall clock at read (per-line, summarized)
const fs = require('fs');
const path = require('path');
const os = require('os');

const [, , sessionCwd, outDir] = process.argv;
const followMsArg = process.argv.indexOf('--follow-ms');
const FOLLOW_MS = followMsArg > -1 ? Number(process.argv[followMsArg + 1]) : 120000;
if (!outDir) { console.error('usage: tail-transcript.js <cwd> <outDir> [--follow-ms N]'); process.exit(1); }
fs.mkdirSync(outDir, { recursive: true });

const projectsRoot = path.join(os.homedir(), '.claude', 'projects');
const ev = (s) => {
  const line = `${new Date().toISOString()} ${s}`;
  fs.appendFileSync(path.join(outDir, 'tailer.log'), line + '\n');
  console.log(line);
};

// --- discovery ---------------------------------------------------------------
const before = new Set();
for (const dir of fs.readdirSync(projectsRoot)) {
  for (const f of safeList(path.join(projectsRoot, dir))) {
    if (f.endsWith('.jsonl')) before.add(path.join(projectsRoot, dir, f));
  }
}
ev(`discovery: snapshot ${before.size} existing transcripts; waiting for a new one...`);

function safeList(p) { try { return fs.readdirSync(p); } catch (_) { return []; } }

const t0 = Date.now();
const findNew = setInterval(() => {
  for (const dir of safeList(projectsRoot)) {
    for (const f of safeList(path.join(projectsRoot, dir))) {
      const full = path.join(projectsRoot, dir, f);
      if (f.endsWith('.jsonl') && !before.has(full)) {
        clearInterval(findNew);
        const discoveryMs = Date.now() - t0;
        ev(`discovery: NEW transcript after ${discoveryMs}ms: ${full}`);
        ev(`discovery: project dir slug = ${dir}`);
        ev(`discovery: session cwd      = ${sessionCwd}`);
        const naive = sessionCwd.replace(/[\\/:. ]/g, '-');
        ev(`discovery: naive slug guess (cwd with [\\/:. ]->'-') = ${naive} ; match=${dir === naive}`);
        tail(full, discoveryMs);
        return;
      }
    }
  }
  if (Date.now() - t0 > 60000) { clearInterval(findNew); ev('discovery: TIMEOUT'); process.exit(1); }
}, 100);

// --- tailing -----------------------------------------------------------------
function tail(file, discoveryMs) {
  let offset = 0;
  let buf = '';
  const state = {
    discoveryMs,
    lines: 0, parsed: 0, malformed: 0,
    types: {}, status: 'starting',
    tokens: { input: 0, output: 0, cacheRead: 0, cacheCreate: 0 },
    tools: [], files: new Set(),
    lags: [], firstLineMs: null, sessionId: null,
  };

  const iv = setInterval(() => {
    let st;
    try { st = fs.statSync(file); } catch (_) { return; }
    if (st.size <= offset) return;
    const fd = fs.openSync(file, 'r');
    const chunk = Buffer.alloc(st.size - offset);
    fs.readSync(fd, chunk, 0, chunk.length, offset);
    fs.closeSync(fd);
    offset = st.size;
    buf += chunk.toString('utf8');
    let nl;
    while ((nl = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, nl); buf = buf.slice(nl + 1);
      if (!line.trim()) continue;
      state.lines++;
      if (state.firstLineMs === null) state.firstLineMs = Date.now() - t0;
      let e;
      try { e = JSON.parse(line); } catch (_) { state.malformed++; continue; }
      state.parsed++;
      handle(e);
    }
    render();
  }, 100);

  function handle(e) {
    const type = e.type || '(untyped)';
    state.types[type] = (state.types[type] || 0) + 1;
    if (e.sessionId) state.sessionId = e.sessionId;
    if (e.timestamp) {
      const lag = Date.now() - Date.parse(e.timestamp);
      if (Number.isFinite(lag)) state.lags.push(lag);
    }
    const usage = e.message && e.message.usage;
    if (usage) {
      state.tokens.input += usage.input_tokens || 0;
      state.tokens.output += usage.output_tokens || 0;
      state.tokens.cacheRead += usage.cache_read_input_tokens || 0;
      state.tokens.cacheCreate += usage.cache_creation_input_tokens || 0;
    }
    const content = e.message && Array.isArray(e.message.content) ? e.message.content : [];
    for (const c of content) {
      if (c && c.type === 'tool_use') {
        state.tools.push(c.name);
        const fp = c.input && (c.input.file_path || c.input.path || c.input.notebook_path);
        if (fp) state.files.add(fp);
        state.status = `working:${c.name}`;
      }
    }
    if (type === 'assistant') state.status = 'working';
    if (type === 'user') state.status = 'working:awaiting-tool-or-turn';
    if (type === 'result' || e.subtype === 'success') state.status = 'done';
  }

  function render() {
    const lag = state.lags.length
      ? `${Math.min(...state.lags)}/${median(state.lags)}/${Math.max(...state.lags)}ms`
      : '-';
    process.stdout.write(
      `\r[status:${state.status}] lines=${state.lines} bad=${state.malformed} ` +
      `tok(in/out/cr)=${state.tokens.input}/${state.tokens.output}/${state.tokens.cacheRead} ` +
      `tools=${state.tools.length} files=${state.files.size} lag(min/med/max)=${lag}   `
    );
  }

  setTimeout(() => {
    clearInterval(iv);
    console.log('');
    const summary = {
      ...state,
      files: [...state.files],
      lags: undefined,
      lagMinMs: state.lags.length ? Math.min(...state.lags) : null,
      lagMedianMs: state.lags.length ? median(state.lags) : null,
      lagMaxMs: state.lags.length ? Math.max(...state.lags) : null,
      lagSamples: state.lags.length,
    };
    fs.writeFileSync(path.join(outDir, 'summary.json'), JSON.stringify(summary, null, 2));
    ev(`tail complete: ${JSON.stringify({ lines: state.lines, malformed: state.malformed, types: state.types })}`);
    process.exit(0);
  }, FOLLOW_MS);
}

function median(a) {
  const s = [...a].sort((x, y) => x - y);
  return s[Math.floor(s.length / 2)];
}

// S-04 tolerant-reader test: append a mix of valid-shaped and garbage lines to
// a synthetic transcript inside a fake projects root, run the tailer's parse
// loop against it, and verify it survives and counts correctly.
// Run: node malformed-test.js <outDir>
const fs = require('fs');
const path = require('path');
const os = require('os');
const { spawnSync } = require('child_process');

const outDir = process.argv[2];
fs.mkdirSync(outDir, { recursive: true });

// Point the tailer at the REAL projects root but a synthetic new file: we
// write into a scratch project dir the CLI never uses.
const projectsRoot = path.join(os.homedir(), '.claude', 'projects');
const fakeDir = path.join(projectsRoot, 's04-malformed-test');
fs.mkdirSync(fakeDir, { recursive: true });
const file = path.join(fakeDir, `synthetic-${process.pid}.jsonl`);

const lines = [
  JSON.stringify({ type: 'assistant', timestamp: new Date().toISOString(), message: { usage: { input_tokens: 10, output_tokens: 5 }, content: [{ type: 'tool_use', name: 'Write', input: { file_path: 'x.txt' } }] } }),
  'this is not json at all {{{',
  JSON.stringify({ type: 'totally-unknown-future-type', payload: { nested: [1, 2, 3] } }),
  '{"truncated": tru',
  JSON.stringify({ type: 'user', timestamp: new Date().toISOString(), message: { content: [{ type: 'tool_result' }] } }),
  '', // blank
  JSON.stringify({ type: 'assistant', message: { usage: { output_tokens: 7 }, content: 'string-content-not-array' } }),
];

// Start the tailer, then append lines with delays (exercises partial reads).
const { spawn } = require('child_process');
const tailer = spawn(process.execPath, [
  path.join(__dirname, 'tail-transcript.js'), 'C:/synthetic', outDir, '--follow-ms', '8000',
], { stdio: ['ignore', 'pipe', 'pipe'] });
let out = '';
tailer.stdout.on('data', (d) => (out += d));
tailer.stderr.on('data', (d) => (out += d));

setTimeout(() => {
  let i = 0;
  const iv = setInterval(() => {
    if (i >= lines.length) return clearInterval(iv);
    fs.appendFileSync(file, lines[i] + '\n');
    i++;
  }, 300);
}, 1500);

tailer.on('exit', (code) => {
  fs.writeFileSync(path.join(outDir, 'malformed-stdout.txt'), out);
  let summary = {};
  try { summary = JSON.parse(fs.readFileSync(path.join(outDir, 'summary.json'), 'utf8')); } catch (_) {}
  const ok =
    code === 0 &&
    summary.lines === 6 &&      // blank line skipped
    summary.malformed === 2 &&  // the two garbage lines
    summary.parsed === 4 &&
    (summary.types || {})['totally-unknown-future-type'] === 1 &&
    summary.tokens && summary.tokens.output === 12;
  console.log(`lines=${summary.lines} malformed=${summary.malformed} parsed=${summary.parsed} exit=${code}`);
  console.log(ok ? 'MALFORMED-TEST PASS' : 'MALFORMED-TEST FAIL');
  try { fs.rmSync(fakeDir, { recursive: true, force: true }); } catch (_) {}
  process.exit(ok ? 0 : 1);
});

// S-05: watch a project's transcript dir during a session that spawns a Task
// subagent; record how sidechain activity appears — same file or separate,
// which fields mark it (isSidechain? parentUuid? agent name?), and with what
// latency subagent tool calls become visible.
//   node tail-all.js <session-cwd-mixed> <outDir> <followMs>
const fs = require('fs');
const path = require('path');
const os = require('os');

const [, , sessionCwd, outDir, followMsArg] = process.argv;
const FOLLOW_MS = Number(followMsArg || 180000);
fs.mkdirSync(outDir, { recursive: true });

const slug = sessionCwd.replace(/[\\/:. ]/g, '-');
const projectsRoot = path.join(os.homedir(), '.claude', 'projects');
const ev = (s) => {
  fs.appendFileSync(path.join(outDir, 'watcher.log'), `${new Date().toISOString()} ${s}\n`);
  console.log(s);
};

// Watch the whole projects root (subagent transcripts might not land in the
// project's own slug dir — that's part of what we're probing), but only files
// created after start.
const before = new Set();
for (const dir of safeList(projectsRoot)) {
  for (const f of safeList(path.join(projectsRoot, dir))) {
    if (f.endsWith('.jsonl')) before.add(path.join(projectsRoot, dir, f));
  }
}
function safeList(p) { try { return fs.readdirSync(p); } catch (_) { return []; } }

const t0 = Date.now();
const tracked = new Map(); // file -> {offset, buf}
const record = []; // per-line observations
const perFile = {};

const iv = setInterval(() => {
  for (const dir of safeList(projectsRoot)) {
    for (const f of safeList(path.join(projectsRoot, dir))) {
      const full = path.join(projectsRoot, dir, f);
      if (!f.endsWith('.jsonl') || before.has(full)) continue;
      if (!tracked.has(full)) {
        tracked.set(full, { offset: 0, buf: '' });
        ev(`NEW FILE +${Date.now() - t0}ms dir=${dir} file=${f} inProjectSlug=${dir === slug}`);
        perFile[full] = { dir, file: f, inProjectSlug: dir === slug, lines: 0, types: {}, sidechainLines: 0, agents: new Set(), tools: [] };
      }
      drain(full);
    }
  }
}, 100);

function drain(full) {
  const t = tracked.get(full);
  let st;
  try { st = fs.statSync(full); } catch (_) { return; }
  if (st.size <= t.offset) return;
  const fd = fs.openSync(full, 'r');
  const chunk = Buffer.alloc(st.size - t.offset);
  fs.readSync(fd, chunk, 0, chunk.length, t.offset);
  fs.closeSync(fd);
  t.offset = st.size;
  t.buf += chunk.toString('utf8');
  let nl;
  while ((nl = t.buf.indexOf('\n')) >= 0) {
    const line = t.buf.slice(0, nl); t.buf = t.buf.slice(nl + 1);
    if (!line.trim()) continue;
    const pf = perFile[full];
    pf.lines++;
    let e;
    try { e = JSON.parse(line); } catch (_) { pf.types['(malformed)'] = (pf.types['(malformed)'] || 0) + 1; continue; }
    const type = e.type || '(untyped)';
    pf.types[type] = (pf.types[type] || 0) + 1;
    if (e.isSidechain) pf.sidechainLines++;
    // hunt for agent identity in plausible places
    for (const k of ['agentName', 'agent', 'subagent_type', 'agentType', 'agentId']) {
      if (e[k]) pf.agents.add(`${k}=${e[k]}`);
    }
    const content = e.message && Array.isArray(e.message.content) ? e.message.content : [];
    for (const c of content) {
      if (c && c.type === 'tool_use') {
        pf.tools.push({ atMs: Date.now() - t0, name: c.name, sidechain: !!e.isSidechain,
          task: c.name === 'Task' ? { desc: c.input && c.input.description, type: c.input && c.input.subagent_type } : undefined });
        if (c.name === 'TodoWrite') {
          record.push({ kind: 'todowrite', atMs: Date.now() - t0, todos: c.input && c.input.todos });
        }
      }
    }
    record.push({
      kind: 'line', atMs: Date.now() - t0, file: path.basename(full), inProjectSlug: pf.inProjectSlug,
      type, isSidechain: !!e.isSidechain, uuid: e.uuid, parentUuid: e.parentUuid, sessionId: e.sessionId,
      lagMs: e.timestamp ? Date.now() - Date.parse(e.timestamp) : null,
    });
  }
}

setTimeout(() => {
  clearInterval(iv);
  for (const pf of Object.values(perFile)) pf.agents = [...pf.agents];
  fs.writeFileSync(path.join(outDir, 'observations.json'), JSON.stringify({ files: perFile, record }, null, 2));
  ev(`done: ${Object.keys(perFile).length} new files, ${record.length} recorded events`);
  process.exit(0);
}, FOLLOW_MS);

