// Launch electron-vite with a cleaned environment. Running from inside an
// Electron-hosted terminal (VS Code, a hosted Claude Code session — i.e. how
// this project dogfoods itself) leaks env vars that break Electron children:
// ELECTRON_RUN_AS_NODE turns our app into plain Node, and
// NoDefaultCurrentDirectoryInExePath breaks native-module gyp builds.
// Spike 01 findings (s-01-pty-host.md) — this is the day-one mitigation.
const { spawnSync } = require('child_process');
const path = require('path');

const env = { ...process.env };
delete env.ELECTRON_RUN_AS_NODE;
delete env.ELECTRON_NO_ATTACH_CONSOLE;
delete env.NoDefaultCurrentDirectoryInExePath;

const bin = path.join(
  __dirname, '..', 'node_modules', '.bin',
  process.platform === 'win32' ? 'electron-vite.cmd' : 'electron-vite'
);
const r = spawnSync(bin, process.argv.slice(2), {
  stdio: 'inherit',
  env,
  shell: process.platform === 'win32',
});
process.exit(r.status ?? 1);

import { defineConfig } from 'electron-vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  main: {},
  preload: {},
  renderer: {
    plugins: [react()],
  },
});

// Window bounds persistence with a missing-display rescue.
// Full workspace/display-fingerprint handling arrives with P1-E2-04 (§7);
// this is the scaffold-level slice: remember bounds, restore them safely.
import { app, screen, BrowserWindow, Rectangle } from 'electron';
import fs from 'fs';
import path from 'path';

export interface WindowState {
  bounds: Rectangle;
  isMaximized: boolean;
}

const DEFAULTS: WindowState = {
  bounds: { x: -1, y: -1, width: 1280, height: 800 },
  isMaximized: false,
};

function stateFile(): string {
  return path.join(app.getPath('userData'), 'window-state.json');
}

export function loadWindowState(): WindowState {
  try {
    const raw = JSON.parse(fs.readFileSync(stateFile(), 'utf8'));
    const merged = mergeState(raw);
    if (!isOnAnyDisplay(merged.bounds)) return DEFAULTS;
    return merged;
  } catch {
    return DEFAULTS;
  }
}

/** Exported for tests: tolerant merge of possibly-corrupt persisted state. */
export function mergeState(raw: unknown): WindowState {
  if (typeof raw !== 'object' || raw === null) return DEFAULTS;
  const r = raw as Partial<WindowState>;
  const b = r.bounds;
  const boundsOk =
    !!b &&
    [b.x, b.y, b.width, b.height].every((n) => Number.isFinite(n)) &&
    (b.width as number) >= 400 &&
    (b.height as number) >= 300;
  return {
    bounds: boundsOk ? (b as Rectangle) : DEFAULTS.bounds,
    isMaximized: r.isMaximized === true,
  };
}

function isOnAnyDisplay(bounds: Rectangle): boolean {
  if (bounds.x === -1 && bounds.y === -1) return true; // "center me" sentinel
  return screen.getAllDisplays().some((d) => {
    const a = d.workArea;
    // at least a 100x100 corner of the window must be visible
    return (
      bounds.x < a.x + a.width - 100 &&
      bounds.x + bounds.width > a.x + 100 &&
      bounds.y < a.y + a.height - 100 &&
      bounds.y + bounds.height > a.y + 40
    );
  });
}

export function trackWindowState(win: BrowserWindow): void {
  let saveTimer: NodeJS.Timeout | null = null;
  const save = () => {
    if (win.isDestroyed()) return;
    const state: WindowState = {
      bounds: win.isMaximized() ? loadLastNormalBounds(win) : win.getNormalBounds(),
      isMaximized: win.isMaximized(),
    };
    try {
      fs.mkdirSync(path.dirname(stateFile()), { recursive: true });
      fs.writeFileSync(stateFile(), JSON.stringify(state));
    } catch {
      // persistence is best-effort; never let it break the app (fail-open)
    }
  };
  const debounced = () => {
    if (saveTimer) clearTimeout(saveTimer);
    saveTimer = setTimeout(save, 500);
  };
  win.on('resize', debounced);
  win.on('move', debounced);
  win.on('maximize', debounced);
  win.on('unmaximize', debounced);
  win.on('close', save);
}

function loadLastNormalBounds(win: BrowserWindow): Rectangle {
  // when maximized, keep the last persisted normal bounds if sane
  try {
    const raw = JSON.parse(fs.readFileSync(stateFile(), 'utf8'));
    return mergeState(raw).bounds;
  } catch {
    return win.getNormalBounds();
  }
}

import { app, BrowserWindow, shell } from 'electron';
import path from 'path';
import { loadWindowState, trackWindowState } from './window-state';

function createWindow(): BrowserWindow {
  const state = loadWindowState();
  const win = new BrowserWindow({
    width: state.bounds.width,
    height: state.bounds.height,
    ...(state.bounds.x !== -1 ? { x: state.bounds.x, y: state.bounds.y } : {}),
    minWidth: 800,
    minHeight: 600,
    show: false,
    backgroundColor: '#1e1e1e',
    webPreferences: {
      preload: path.join(__dirname, '../preload/index.js'),
      sandbox: true,
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  if (state.isMaximized) win.maximize();
  trackWindowState(win);
  win.once('ready-to-show', () => win.show());

  // external links open in the OS browser, never in-app
  win.webContents.setWindowOpenHandler(({ url }) => {
    void shell.openExternal(url);
    return { action: 'deny' };
  });

  if (process.env.ELECTRON_RENDERER_URL) {
    void win.loadURL(process.env.ELECTRON_RENDERER_URL);
  } else {
    void win.loadFile(path.join(__dirname, '../renderer/index.html'));
  }
  return win;
}

app.whenReady().then(() => {
  createWindow();
  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });

  // SWITCHBOARD_AUTOCLOSE=<seconds>: scripted smoke checks (spike pattern)
  const autoclose = Number(process.env.SWITCHBOARD_AUTOCLOSE);
  if (Number.isFinite(autoclose) && autoclose > 0) {
    setTimeout(() => app.quit(), autoclose * 1000);
  }
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});

import { contextBridge } from 'electron';

// The bridge grows with each subsystem (sessions, hooks, git...). Scaffold
// exposes only inert metadata to prove the isolation wiring works.
const api = {
  appVersion: process.env.npm_package_version ?? 'dev',
  platform: process.platform,
};

contextBridge.exposeInMainWorld('switchboard', api);

export type SwitchboardApi = typeof api;

import React from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';

createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React from 'react';

// Scaffold shell — real layout arrives with P1-E3-01. Deliberately unstyled
// beyond proving the renderer boots; theme tokens land in P1-E1-03.
export function App(): React.JSX.Element {
  return (
    <main
      style={{
        fontFamily: 'system-ui, sans-serif',
        color: '#d4d4d4',
        background: '#1e1e1e',
        minHeight: '100vh',
        display: 'grid',
        placeItems: 'center',
        margin: 0,
      }}
    >
      <div>
        <h1 style={{ fontWeight: 300 }}>switchboard</h1>
        <p style={{ opacity: 0.6 }}>
          scaffold OK — {window.switchboard.platform} · v{window.switchboard.appVersion}
        </p>
      </div>
    </main>
  );
}

import type { SwitchboardApi } from '../../preload';

declare global {
  interface Window {
    switchboard: SwitchboardApi;
  }
}

