import { describe, it, expect } from 'vitest';
import { pseudolocalize, pseudolocalizeResource } from './pseudo';
import en from './locales/en.json';

function leafStrings(node: unknown, acc: string[] = []): string[] {
  if (typeof node === 'string') acc.push(node);
  else if (typeof node === 'object' && node !== null) {
    for (const v of Object.values(node)) leafStrings(v, acc);
  }
  return acc;
}

describe('pseudolocalize', () => {
  it('wraps and mangles plain text', () => {
    const out = pseudolocalize('Session done');
    expect(out.startsWith('⟦')).toBe(true);
    expect(out.endsWith('⟧')).toBe(true);
    expect(out).not.toContain('Session');
  });

  it('preserves ICU argument blocks verbatim', () => {
    const out = pseudolocalize('theme: {theme} of {count, number}');
    expect(out).toContain('{theme}');
    expect(out).toContain('{count, number}');
  });

  it('mangles EVERY leaf string of the real en.json (the done-when)', () => {
    const pseudo = pseudolocalizeResource(en);
    const before = leafStrings(en);
    const after = leafStrings(pseudo);
    expect(after).toHaveLength(before.length);
    for (const s of after) {
      expect(s.startsWith('⟦')).toBe(true);
      expect(s.endsWith('⟧')).toBe(true);
    }
    // and none survive unmangled
    for (let i = 0; i < before.length; i++) {
      expect(after[i]).not.toBe(before[i]);
    }
  });
});

// Redaction layer (§5.22): secrets never reach disk. Two nets, both always on:
//  1. key-based — any field whose name smells like a credential
//  2. value-based — any string that matches known secret shapes
// False positives are acceptable; leaked tokens are not.

const SECRET_KEY_RE = /(token|secret|password|passwd|credential|api[-_]?key|authorization|cookie|bearer)/i;

const SECRET_VALUE_RES: RegExp[] = [
  /sk-[A-Za-z0-9_-]{10,}/g, // API-key style (incl. sk-ant-...)
  /(?:Bearer|Basic)\s+[A-Za-z0-9+/._=-]{8,}/gi,
  /gh[pousr]_[A-Za-z0-9]{20,}/g, // GitHub tokens
  /eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}/g, // JWT
  /\b[0-9a-f]{32,}\b/gi, // long hex (session tokens, hashes-as-secrets)
];

export const REDACTED = '[REDACTED]';

export function redactString(s: string): string {
  let out = s;
  for (const re of SECRET_VALUE_RES) out = out.replace(re, REDACTED);
  return out;
}

/** Deep-redact any JSON-serializable value. Cycles are cut, not followed. */
export function redactValue(v: unknown, keyHint?: string, seen = new WeakSet<object>()): unknown {
  if (keyHint && SECRET_KEY_RE.test(keyHint)) return REDACTED;
  if (typeof v === 'string') return redactString(v);
  if (typeof v !== 'object' || v === null) return v;
  if (seen.has(v)) return '[CYCLE]';
  seen.add(v);
  if (Array.isArray(v)) return v.map((x) => redactValue(x, undefined, seen));
  return Object.fromEntries(
    Object.entries(v as Record<string, unknown>).map(([k, x]) => [k, redactValue(x, k, seen)])
  );
}

// Logging pipeline (§5.22): JSON-lines to rotating files. Zero-dep by intent —
// the logger is load-bearing for debugging the app; it must not have its own
// dependency surface. Redaction is applied to every record, unconditionally.
//
// Line shape: {"ts","level","subsystem","sessionId"?,"msg",...fields}
// Debug lines are suppressed unless the subsystem is enabled via
// SWITCHBOARD_DEBUG="pty,hooks" (or "*").
import fs from 'fs';
import path from 'path';
import { redactValue } from './redact';

export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

export interface LoggerOptions {
  dir: string;
  maxBytes?: number; // rotate threshold per file
  maxFiles?: number; // rotated files kept
  debugSubsystems?: string; // comma list or '*'; default from env
}

export interface LogFields {
  sessionId?: string;
  [key: string]: unknown;
}

const DEFAULTS = { maxBytes: 5 * 1024 * 1024, maxFiles: 5 };

export class LogSink {
  private readonly dir: string;
  private readonly maxBytes: number;
  private readonly maxFiles: number;
  private readonly debugSet: Set<string> | 'all' | 'none';

  constructor(opts: LoggerOptions) {
    this.dir = opts.dir;
    this.maxBytes = opts.maxBytes ?? DEFAULTS.maxBytes;
    this.maxFiles = opts.maxFiles ?? DEFAULTS.maxFiles;
    const dbg = opts.debugSubsystems ?? process.env.SWITCHBOARD_DEBUG ?? '';
    this.debugSet =
      dbg === '*' ? 'all' : dbg.trim() === '' ? 'none' : new Set(dbg.split(',').map((s) => s.trim()));
    fs.mkdirSync(this.dir, { recursive: true });
  }

  get file(): string {
    return path.join(this.dir, 'switchboard.log');
  }

  debugEnabled(subsystem: string): boolean {
    return this.debugSet === 'all' || (this.debugSet !== 'none' && this.debugSet.has(subsystem));
  }

  write(level: LogLevel, subsystem: string, msg: string, fields?: LogFields): void {
    if (level === 'debug' && !this.debugEnabled(subsystem)) return;
    const record = {
      ts: new Date().toISOString(),
      level,
      subsystem,
      msg,
      ...(fields ? (redactValue(fields) as object) : {}),
    };
    // msg goes through value redaction too
    const line = JSON.stringify({ ...record, msg: redactValue(msg) }) + '\n';
    try {
      this.rotateIfNeeded(Buffer.byteLength(line));
      fs.appendFileSync(this.file, line);
    } catch {
      // logging must never take the app down (fail-open)
    }
  }

  private rotateIfNeeded(incoming: number): void {
    let size = 0;
    try {
      size = fs.statSync(this.file).size;
    } catch {
      return; // no file yet
    }
    if (size + incoming <= this.maxBytes) return;
    for (let i = this.maxFiles - 1; i >= 1; i--) {
      const from = i === 1 ? this.file : `${this.file}.${i - 1}`;
      const to = `${this.file}.${i}`;
      try {
        fs.rmSync(to, { force: true });
        if (fs.existsSync(from)) fs.renameSync(from, to);
      } catch {
        /* best-effort */
      }
    }
  }
}

export interface Logger {
  debug: (msg: string, fields?: LogFields) => void;
  info: (msg: string, fields?: LogFields) => void;
  warn: (msg: string, fields?: LogFields) => void;
  error: (msg: string, fields?: LogFields) => void;
  child: (fields: LogFields) => Logger;
}

export function createLogger(sink: LogSink, subsystem: string, bound: LogFields = {}): Logger {
  const emit =
    (level: LogLevel) =>
    (msg: string, fields?: LogFields): void =>
      sink.write(level, subsystem, msg, { ...bound, ...fields });
  return {
    debug: emit('debug'),
    info: emit('info'),
    warn: emit('warn'),
    error: emit('error'),
    child: (fields) => createLogger(sink, subsystem, { ...bound, ...fields }),
  };
}

import { describe, it, expect, beforeEach } from 'vitest';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { LogSink, createLogger } from './logger';
import { redactValue, REDACTED } from './redact';

let dir: string;
beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'sb-log-'));
});

function lines(sink: LogSink): Array<Record<string, unknown>> {
  return fs
    .readFileSync(sink.file, 'utf8')
    .trim()
    .split('\n')
    .map((l) => JSON.parse(l));
}

describe('redaction (the done-when)', () => {
  it('redacts a token passed through log args', () => {
    const sink = new LogSink({ dir });
    const log = createLogger(sink, 'hooks');
    log.info('listener ready', { token: 'super-secret-value', port: 4711 });
    log.info('spawn', { cmd: 'claude --token sk-ant-abc12345678901234567890' });
    const [a, b] = lines(sink);
    expect(a.token).toBe(REDACTED);
    expect(a.port).toBe(4711);
    expect(JSON.stringify(b)).not.toContain('sk-ant-');
  });

  it('redacts by key smell and value shape, deep', () => {
    const v = redactValue({
      nested: { apiKey: 'x', note: 'Bearer abcdef123456789' },
      hex: 'deadbeefdeadbeefdeadbeefdeadbeefdeadbeef',
    }) as Record<string, Record<string, unknown>> & { hex: string };
    expect(v.nested.apiKey).toBe(REDACTED);
    expect(v.nested.note).toContain(REDACTED);
    expect(v.hex).toBe(REDACTED);
  });
});

describe('json-lines + subsystem/sessionId fields', () => {
  it('one session lifecycle reconstructs with a single filter', () => {
    const sink = new LogSink({ dir });
    const sessions = createLogger(sink, 'sessions');
    const pty = createLogger(sink, 'pty');
    const s1 = sessions.child({ sessionId: 's-111' });
    const noise = sessions.child({ sessionId: 's-999' });

    s1.info('created');
    noise.info('created');
    createLogger(sink, 'ui').info('window focused');
    pty.info('spawned', { sessionId: 's-111', pid: 42 });
    s1.info('status', { to: 'working' });
    s1.info('status', { to: 'done' });
    noise.info('killed');

    const l = lines(sink).filter((r) => r.sessionId === 's-111');
    expect(l.map((r) => r.msg)).toEqual(['created', 'spawned', 'status', 'status']);
    expect(l.map((r) => r.subsystem)).toEqual(['sessions', 'pty', 'sessions', 'sessions']);
  });
});

describe('debug toggles', () => {
  it('suppresses debug unless subsystem enabled', () => {
    const sink = new LogSink({ dir, debugSubsystems: 'pty' });
    createLogger(sink, 'pty').debug('visible');
    createLogger(sink, 'hooks').debug('hidden');
    createLogger(sink, 'hooks').info('info always');
    const msgs = lines(sink).map((r) => r.msg);
    expect(msgs).toEqual(['visible', 'info always']);
  });

  it('star enables all', () => {
    const sink = new LogSink({ dir, debugSubsystems: '*' });
    createLogger(sink, 'anything').debug('x');
    expect(lines(sink)).toHaveLength(1);
  });
});

describe('rotation', () => {
  it('rotates at maxBytes and keeps maxFiles', () => {
    const sink = new LogSink({ dir, maxBytes: 500, maxFiles: 3 });
    const log = createLogger(sink, 'rot');
    for (let i = 0; i < 60; i++) log.info(`line ${i} ${'x'.repeat(40)}`);
    const files = fs.readdirSync(dir).sort();
    expect(files).toContain('switchboard.log');
    expect(files.length).toBeLessThanOrEqual(3 + 1); // live + rotated
    expect(fs.statSync(sink.file).size).toBeLessThanOrEqual(600);
  });
});

