// Extensibility seams v0 (§5.23): every pluggable surface goes through a
// contribution point + capability manifest, even while everything is
// in-process. The seam is the product decision; out-of-process loading can
// arrive later without rewiring consumers.

/** What a contributor declares about itself. */
export interface CapabilityManifest {
  /** unique id, kebab-case, e.g. "claude-code" */
  id: string;
  displayName: string;
  version: string;
  /** capability strings, e.g. "sessions.spawn", "events.emit" */
  capabilities: string[];
}

/** Known contribution points (grows with the app). */
export type ContributionPointId = 'provider-adapter' | 'event-source';

/**
 * Provider adapter contract v0 (§5.3). The full interface grows in P1-E2-02;
 * v0 covers what a session manager needs to spawn a CLI.
 */
export interface ProviderAdapter {
  manifest: CapabilityManifest;
  /** Build the spawn recipe for a session in `cwd`. */
  buildSpawn(options: SpawnOptions): SpawnRecipe;
}

export interface SpawnOptions {
  cwd: string;
  resumeSessionId?: string;
}

export interface SpawnRecipe {
  command: string;
  args: string[];
  /** env DELTAS applied over a scrubbed process env (see S-01 findings) */
  env: Record<string, string | undefined>;
}

/** Event-source contract v0 (feeds the §5.12 event stream). */
export interface EventSource {
  manifest: CapabilityManifest;
  /** subscribe returns an unsubscribe */
  subscribe(listener: (event: ContributedEvent) => void): () => void;
}

export interface ContributedEvent {
  sourceId: string;
  sessionId?: string;
  kind: string;
  at: string; // ISO
  data?: unknown;
}

/** Map from contribution point to its contract type. */
export interface ContributionContracts {
  'provider-adapter': ProviderAdapter;
  'event-source': EventSource;
}

// In-process contribution registry (§5.23). Consumers resolve contracts by
// contribution point + id (or capability) — never by importing a contributor
// module directly. That rule is what keeps the seam real.
import { CapabilityManifest, ContributionContracts, ContributionPointId } from './contributions';

type Registered<P extends ContributionPointId> = ContributionContracts[P];

export class ContributionRegistry {
  private readonly points = new Map<ContributionPointId, Map<string, { manifest: CapabilityManifest }>>();

  register<P extends ContributionPointId>(point: P, contribution: Registered<P>): void {
    const byId = this.points.get(point) ?? new Map();
    const id = contribution.manifest.id;
    if (byId.has(id)) {
      throw new Error(`duplicate contribution "${id}" at point "${point}"`);
    }
    byId.set(id, contribution);
    this.points.set(point, byId);
  }

  resolve<P extends ContributionPointId>(point: P, id: string): Registered<P> | undefined {
    return this.points.get(point)?.get(id) as Registered<P> | undefined;
  }

  /** All contributions at a point, optionally filtered by capability. */
  list<P extends ContributionPointId>(point: P, capability?: string): Registered<P>[] {
    const all = [...(this.points.get(point)?.values() ?? [])] as Registered<P>[];
    return capability
      ? all.filter((c) => c.manifest.capabilities.includes(capability))
      : all;
  }

  manifests(): Array<{ point: ContributionPointId; manifest: CapabilityManifest }> {
    return [...this.points.entries()].flatMap(([point, byId]) =>
      [...byId.values()].map((c) => ({ point, manifest: c.manifest }))
    );
  }
}

/** The app-wide registry instance, populated at bootstrap. */
export const registry = new ContributionRegistry();

// Claude Code provider adapter v0 — registered via the contribution registry
// (§5.23); nothing outside bootstrap may import this module directly.
// The spawn recipe implements the S-01/S-02 verdicts; the full adapter
// (settings generation, validation, hook wiring) lands in P1-E2-02.
import { ProviderAdapter, SpawnOptions, SpawnRecipe } from '../extensibility/contributions';

export const claudeAdapter: ProviderAdapter = {
  manifest: {
    id: 'claude-code',
    displayName: 'Claude Code',
    version: '0.1.0',
    capabilities: ['sessions.spawn'],
  },

  buildSpawn(options: SpawnOptions): SpawnRecipe {
    const args: string[] = [];
    if (options.resumeSessionId) args.push('--resume', options.resumeSessionId);
    return {
      // P1-E2-02 resolves this to an absolute path before spawn (S-01:
      // PATH-relative .cmd with cwd=user project is a planted-binary footgun)
      command: 'claude.cmd',
      args,
      env: {
        // S-01 landmines: never let these leak into a hosted session
        ELECTRON_RUN_AS_NODE: undefined,
        ELECTRON_NO_ATTACH_CONSOLE: undefined,
      },
    };
  },
};

// Bootstrap: the ONLY module allowed to import contributors directly — it
// populates the registry; everyone else resolves through it (§5.23).
import { registry } from './extensibility/registry';
import { claudeAdapter } from './providers/claude';

export function registerBuiltinContributions(): void {
  registry.register('provider-adapter', claudeAdapter);
}

import { describe, it, expect } from 'vitest';
import { ContributionRegistry } from './registry';
import { ProviderAdapter } from './contributions';
import { claudeAdapter } from '../providers/claude';

function fakeAdapter(id: string, capabilities: string[] = ['sessions.spawn']): ProviderAdapter {
  return {
    manifest: { id, displayName: id, version: '0.0.0', capabilities },
    buildSpawn: () => ({ command: 'x', args: [], env: {} }),
  };
}

describe('ContributionRegistry', () => {
  it('registers and resolves by point + id', () => {
    const r = new ContributionRegistry();
    r.register('provider-adapter', fakeAdapter('a'));
    expect(r.resolve('provider-adapter', 'a')?.manifest.id).toBe('a');
    expect(r.resolve('provider-adapter', 'nope')).toBeUndefined();
  });

  it('rejects duplicate ids at the same point', () => {
    const r = new ContributionRegistry();
    r.register('provider-adapter', fakeAdapter('dup'));
    expect(() => r.register('provider-adapter', fakeAdapter('dup'))).toThrow(/duplicate/);
  });

  it('lists by capability', () => {
    const r = new ContributionRegistry();
    r.register('provider-adapter', fakeAdapter('a', ['sessions.spawn']));
    r.register('provider-adapter', fakeAdapter('b', ['other.cap']));
    const spawners = r.list('provider-adapter', 'sessions.spawn');
    expect(spawners.map((s) => s.manifest.id)).toEqual(['a']);
  });

  it('exposes manifests for future about/debug UI', () => {
    const r = new ContributionRegistry();
    r.register('provider-adapter', fakeAdapter('a'));
    expect(r.manifests()).toEqual([
      { point: 'provider-adapter', manifest: expect.objectContaining({ id: 'a' }) },
    ]);
  });
});

describe('claude adapter through the registry (the done-when)', () => {
  it('is resolvable via the registry and builds a spawn recipe', () => {
    const r = new ContributionRegistry();
    r.register('provider-adapter', claudeAdapter);
    const adapter = r.resolve('provider-adapter', 'claude-code');
    expect(adapter).toBeDefined();
    const recipe = adapter!.buildSpawn({ cwd: 'C:/tmp/x', resumeSessionId: 'abc' });
    expect(recipe.args).toEqual(['--resume', 'abc']);
    // S-01 env landmines scrubbed in the recipe
    expect('ELECTRON_RUN_AS_NODE' in recipe.env).toBe(true);
    expect(recipe.env.ELECTRON_RUN_AS_NODE).toBeUndefined();
  });
});

