// Rebuild native modules (node-pty) against Electron's ABI. Runs on
// postinstall so fresh clones and CI just work.
//
// Windows landmines (spike findings s-01-pty-host.md):
//  - NoDefaultCurrentDirectoryInExePath breaks winpty's gyp — always unset.
//  - node-pty wants Spectre-mitigated MSVC libs (MSB8040). The sanctioned fix
//    is installing the VS component ("MSVC Spectre-mitigated libs"); if the
//    build fails without it we strip the gyp setting and retry, loudly.
const { spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const env = { ...process.env };
delete env.NoDefaultCurrentDirectoryInExePath;
delete env.ELECTRON_RUN_AS_NODE;

function rebuild() {
  return spawnSync('npx', ['electron-rebuild', '-f', '-w', 'node-pty'], {
    stdio: 'inherit',
    shell: true,
    env,
  });
}

let r = rebuild();
if (r.status !== 0 && process.platform === 'win32') {
  console.warn(
    '[rebuild-native] build failed — retrying with SpectreMitigation stripped.\n' +
      '[rebuild-native] sanctioned fix: install the "MSVC Spectre-mitigated libs" VS component.'
  );
  const ptyDir = path.join(__dirname, '..', 'node_modules', 'node-pty');
  for (const rel of ['binding.gyp', 'deps/winpty/src/winpty.gyp']) {
    const f = path.join(ptyDir, rel);
    try {
      const src = fs.readFileSync(f, 'utf8');
      const out = src.replace(/^.*'SpectreMitigation'.*\r?\n/gm, '');
      if (out !== src) fs.writeFileSync(f, out);
    } catch {
      /* file layout changed — let the retry surface the real error */
    }
  }
  r = rebuild();
}
process.exit(r.status ?? 1);

// Byte ring buffer for PTY scrollback (S-07 verdict: hidden panes don't
// render — they ingest into a capped buffer; xterm attaches on focus and
// replays this). Cap ~ scrollback 5000 lines of typical TUI output.
export class RingBuffer {
  private chunks: Buffer[] = [];
  private total = 0;

  constructor(private readonly maxBytes: number) {
    if (maxBytes <= 0) throw new Error('maxBytes must be > 0');
  }

  push(data: Buffer): void {
    this.chunks.push(data);
    this.total += data.length;
    while (this.total > this.maxBytes && this.chunks.length > 1) {
      const dropped = this.chunks.shift()!;
      this.total -= dropped.length;
    }
    // single oversized chunk: keep only its tail
    if (this.total > this.maxBytes && this.chunks.length === 1) {
      const only = this.chunks[0];
      this.chunks[0] = only.subarray(only.length - this.maxBytes);
      this.total = this.maxBytes;
    }
  }

  get byteLength(): number {
    return this.total;
  }

  /** Full buffered contents (for attach-on-focus replay). */
  snapshot(): Buffer {
    return Buffer.concat(this.chunks, this.total);
  }

  clear(): void {
    this.chunks = [];
    this.total = 0;
  }
}

// PtyService (P1-E2-01): generic PTY lifecycle — spawn/resize/write/kill —
// with per-session scrollback ring buffers. Provider-specific spawn recipes
// come from adapters via the contribution registry; this service is dumb
// about what it hosts.
//
// Deliberately electron-free: loadable under any Node-ABI-compatible runtime
// (the lifecycle check runs it under `electron --run-as-node`).
import * as pty from 'node-pty';
import { RingBuffer } from './ring-buffer';

export interface PtySpawnOptions {
  id: string;
  command: string;
  args: string[];
  cwd: string;
  /** env DELTAS over the (scrubbed) base env; undefined value = delete key */
  env?: Record<string, string | undefined>;
  cols?: number;
  rows?: number;
  scrollbackBytes?: number;
}

export interface PtySessionInfo {
  id: string;
  pid: number;
  exitCode: number | null;
}

// S-01 landmines: these must never leak from our process into a hosted CLI.
const SCRUB_ALWAYS = ['ELECTRON_RUN_AS_NODE', 'ELECTRON_NO_ATTACH_CONSOLE'];

export function buildEnv(
  base: NodeJS.ProcessEnv,
  deltas?: Record<string, string | undefined>
): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = { ...base };
  for (const k of SCRUB_ALWAYS) delete env[k];
  for (const [k, v] of Object.entries(deltas ?? {})) {
    if (v === undefined) delete env[k];
    else env[k] = v;
  }
  return env;
}

export class PtySession {
  readonly id: string;
  readonly scrollback: RingBuffer;
  private readonly proc: pty.IPty;
  private dataListeners = new Set<(d: string) => void>();
  private exitListeners = new Set<(code: number) => void>();
  exitCode: number | null = null;

  constructor(opts: PtySpawnOptions) {
    this.id = opts.id;
    this.scrollback = new RingBuffer(opts.scrollbackBytes ?? 2 * 1024 * 1024);
    this.proc = pty.spawn(opts.command, opts.args, {
      name: 'xterm-256color',
      cols: opts.cols ?? 120,
      rows: opts.rows ?? 30,
      cwd: opts.cwd,
      env: buildEnv(process.env, opts.env) as { [k: string]: string },
      useConpty: process.platform === 'win32',
    });
    this.proc.onData((d) => {
      this.scrollback.push(Buffer.from(d, 'utf8'));
      for (const l of this.dataListeners) l(d);
    });
    this.proc.onExit(({ exitCode }) => {
      this.exitCode = exitCode;
      for (const l of this.exitListeners) l(exitCode);
    });
  }

  get pid(): number {
    return this.proc.pid;
  }

  onData(listener: (d: string) => void): () => void {
    this.dataListeners.add(listener);
    return () => this.dataListeners.delete(listener);
  }

  onExit(listener: (code: number) => void): () => void {
    this.exitListeners.add(listener);
    return () => this.exitListeners.delete(listener);
  }

  write(data: string): void {
    if (this.exitCode !== null) return; // dead PTY: writes raise async socket errors (S-01)
    this.proc.write(data);
  }

  resize(cols: number, rows: number): void {
    if (this.exitCode !== null) return;
    if (!Number.isInteger(cols) || !Number.isInteger(rows) || cols <= 0 || rows <= 0) return;
    this.proc.resize(cols, rows);
  }

  kill(): void {
    try {
      this.proc.kill();
    } catch {
      /* already dead */
    }
  }
}

export class PtyService {
  private readonly sessions = new Map<string, PtySession>();

  spawn(opts: PtySpawnOptions): PtySession {
    if (this.sessions.has(opts.id)) {
      throw new Error(`pty session "${opts.id}" already exists`);
    }
    const s = new PtySession(opts);
    this.sessions.set(opts.id, s);
    s.onExit(() => {
      /* keep the entry: exitCode is part of session state; SessionManager
         decides when to drop it */
    });
    return s;
  }

  get(id: string): PtySession | undefined {
    return this.sessions.get(id);
  }

  remove(id: string): void {
    const s = this.sessions.get(id);
    if (s && s.exitCode === null) s.kill();
    this.sessions.delete(id);
  }

  list(): PtySessionInfo[] {
    return [...this.sessions.values()].map((s) => ({ id: s.id, pid: s.pid, exitCode: s.exitCode }));
  }

  killAll(): void {
    for (const s of this.sessions.values()) s.kill();
  }
}

import { describe, it, expect } from 'vitest';
import { RingBuffer } from './ring-buffer';
import { buildEnv } from './pty-service';

describe('RingBuffer', () => {
  it('keeps everything under the cap', () => {
    const rb = new RingBuffer(100);
    rb.push(Buffer.from('a'.repeat(40)));
    rb.push(Buffer.from('b'.repeat(40)));
    expect(rb.byteLength).toBe(80);
    expect(rb.snapshot().toString()).toBe('a'.repeat(40) + 'b'.repeat(40));
  });

  it('drops oldest chunks past the cap', () => {
    const rb = new RingBuffer(100);
    rb.push(Buffer.from('a'.repeat(60)));
    rb.push(Buffer.from('b'.repeat(60)));
    expect(rb.byteLength).toBe(60);
    expect(rb.snapshot().toString()).toBe('b'.repeat(60));
  });

  it('keeps the tail of a single oversized chunk', () => {
    const rb = new RingBuffer(10);
    rb.push(Buffer.from('0123456789abcdef'));
    expect(rb.snapshot().toString()).toBe('6789abcdef');
  });

  it('clear resets', () => {
    const rb = new RingBuffer(10);
    rb.push(Buffer.from('xyz'));
    rb.clear();
    expect(rb.byteLength).toBe(0);
    expect(rb.snapshot().length).toBe(0);
  });
});

