// Session status state machine (P1-E2-03), semantics from the S-06 findings:
//   - hooks are the transition authority (Stop ~30ms; transcript has no
//     done-marker)
//   - permission Notification is a debounced backup signal; our own
//     PreToolUse hold is authoritative when present (E2-05/Phase 2)
//   - no event fires on prompt acceptance: any working-ish event clears
//     needs-* states
//   - unknown events: log, don't transition (§5.26 posture)
export type SessionStatus =
  | 'starting'
  | 'working'
  | 'needs-input'
  | 'needs-permission'
  | 'idle'
  | 'done'
  | 'crashed';

export type SessionEvent =
  | { kind: 'hook'; event: 'SessionStart' }
  | { kind: 'hook'; event: 'UserPromptSubmit' }
  | { kind: 'hook'; event: 'PreToolUse'; tool?: string }
  | { kind: 'hook'; event: 'PostToolUse'; tool?: string }
  | { kind: 'hook'; event: 'Notification'; notificationType?: string; message?: string }
  | { kind: 'hook'; event: 'Stop' }
  | { kind: 'hook'; event: 'SubagentStop' }
  | { kind: 'hook'; event: string } // forward-compat: unknown hook events
  | { kind: 'permission-held' } // our PreToolUse round-trip is pending (E2-05+)
  | { kind: 'permission-resolved' }
  | { kind: 'user-input' } // user typed into the terminal
  | { kind: 'exit'; code: number };

export interface TransitionResult {
  status: SessionStatus;
  changed: boolean;
  /** transient markers that aren't status changes (subagent-done etc.) */
  note?: string;
}

export function transition(current: SessionStatus, ev: SessionEvent): TransitionResult {
  const to = (status: SessionStatus, note?: string): TransitionResult => ({
    status,
    changed: status !== current,
    note,
  });
  const stay = (note?: string): TransitionResult => ({ status: current, changed: false, note });

  // terminal-ish: crashed only leaves via restart (manager re-creates)
  if (current === 'crashed' && ev.kind !== 'hook') {
    if (ev.kind === 'exit') return stay();
  }

  switch (ev.kind) {
    case 'exit':
      // done -> exit(0) is a normal wind-down, not a crash
      return ev.code === 0 || current === 'done' ? to('done') : to('crashed');
    case 'permission-held':
      return to('needs-permission');
    case 'permission-resolved':
      return to('working');
    case 'user-input':
      // typing answers whatever was being waited on
      return current === 'needs-input' || current === 'needs-permission' || current === 'idle'
        ? to('working')
        : stay();
    case 'hook':
      switch (ev.event) {
        case 'SessionStart':
          return to('starting');
        case 'UserPromptSubmit':
          return to('working');
        case 'PreToolUse':
        case 'PostToolUse':
          return to('working');
        case 'Notification': {
          const n = ev as { notificationType?: string; message?: string };
          const blob = `${n.notificationType ?? ''} ${n.message ?? ''}`;
          if (/permission/i.test(blob)) return to('needs-permission');
          if (/waiting|input|idle/i.test(blob)) return to('needs-input');
          return stay(`notification:${n.notificationType ?? 'unknown'}`);
        }
        case 'Stop':
          return to('done');
        case 'SubagentStop':
          return stay('subagent-done');
        default:
          return stay(`unknown-hook:${ev.event}`);
      }
  }
}

// SessionManager (P1-E2-03): create/kill/restart sessions, identity registry,
// status state machine fed by hook events (ingestion point here; the live
// HookListener wires into it in P1-E2-05). Every transition is logged with
// sessionId (queryable per the E1-05 logging contract) and observable via
// subscription.
import { randomUUID } from 'crypto';
import { ContributionRegistry } from '../extensibility/registry';
import { SpawnRecipe } from '../extensibility/contributions';
import { Logger } from '../log/logger';
import { SessionEvent, SessionStatus, transition } from './state-machine';

export interface SessionIdentity {
  title: string;
  folder: string;
  accentColor?: string;
  providerId: string;
}

export interface SessionRecord {
  id: string;
  identity: SessionIdentity;
  status: SessionStatus;
  createdAt: string;
  nativeSessionId?: string;
  pid?: number;
  exitCode: number | null;
}

/** The slice of PtyService the manager needs — injectable for tests. */
export interface PtyLike {
  spawn(opts: {
    id: string;
    command: string;
    args: string[];
    cwd: string;
    env?: Record<string, string | undefined>;
  }): {
    pid: number;
    onExit(l: (code: number) => void): () => void;
    kill(): void;
  };
  remove(id: string): void;
}

export interface StatusChange {
  sessionId: string;
  from: SessionStatus;
  to: SessionStatus;
  cause: string;
  at: string;
}

export class SessionManager {
  private readonly sessions = new Map<string, SessionRecord>();
  private readonly listeners = new Set<(c: StatusChange) => void>();
  private readonly history: StatusChange[] = [];

  constructor(
    private readonly registry: ContributionRegistry,
    private readonly ptys: PtyLike,
    private readonly log: Logger,
    private readonly stateDir: string
  ) {}

  create(identity: SessionIdentity, opts?: { resumeSessionId?: string; settings?: Record<string, unknown> }): SessionRecord {
    const adapter = this.registry.resolve('provider-adapter', identity.providerId);
    if (!adapter) throw new Error(`no provider adapter "${identity.providerId}"`);
    const id = randomUUID();
    const recipe: SpawnRecipe = adapter.buildSpawn({
      cwd: identity.folder,
      sessionId: id,
      stateDir: this.stateDir,
      resumeSessionId: opts?.resumeSessionId,
      settings: opts?.settings,
    });
    const record: SessionRecord = {
      id,
      identity,
      status: 'starting',
      createdAt: new Date().toISOString(),
      exitCode: null,
    };
    this.sessions.set(id, record);
    const proc = this.ptys.spawn({ id, command: recipe.command, args: recipe.args, cwd: identity.folder, env: recipe.env });
    record.pid = proc.pid;
    proc.onExit((code) => {
      record.exitCode = code;
      this.apply(id, { kind: 'exit', code });
    });
    this.log.info('session created', { sessionId: id, folder: identity.folder, pid: proc.pid, provider: identity.providerId });
    return { ...record };
  }

  kill(id: string): void {
    const r = this.mustGet(id);
    this.ptys.remove(id);
    this.log.info('session killed', { sessionId: id });
    // exit handler flips status via the 'exit' event; nothing else to do
    void r;
  }

  restart(id: string): SessionRecord {
    const r = this.mustGet(id);
    this.ptys.remove(id);
    this.sessions.delete(id);
    this.log.info('session restarting', { sessionId: id });
    return this.create(r.identity, { resumeSessionId: r.nativeSessionId });
  }

  /** Hook/permission/user events feed the state machine here. */
  apply(id: string, ev: SessionEvent): void {
    const r = this.sessions.get(id);
    if (!r) return; // late events for removed sessions are dropped, not fatal
    const result = transition(r.status, ev);
    if (result.note) this.log.debug('session event note', { sessionId: id, note: result.note });
    if (!result.changed) return;
    const change: StatusChange = {
      sessionId: id,
      from: r.status,
      to: result.status,
      cause: describeCause(ev),
      at: new Date().toISOString(),
    };
    r.status = result.status;
    this.history.push(change);
    this.log.info('session status', { sessionId: id, from: change.from, to: change.to, cause: change.cause });
    for (const l of this.listeners) l(change);
  }

  setNativeSessionId(id: string, nativeId: string): void {
    const r = this.sessions.get(id);
    if (r) r.nativeSessionId = nativeId;
  }

  get(id: string): SessionRecord | undefined {
    const r = this.sessions.get(id);
    return r ? { ...r } : undefined;
  }

  list(): SessionRecord[] {
    return [...this.sessions.values()].map((r) => ({ ...r }));
  }

  /** Queryable transition history (the done-when observability). */
  transitions(sessionId?: string): StatusChange[] {
    return sessionId ? this.history.filter((h) => h.sessionId === sessionId) : [...this.history];
  }

  onStatusChange(l: (c: StatusChange) => void): () => void {
    this.listeners.add(l);
    return () => this.listeners.delete(l);
  }

  private mustGet(id: string): SessionRecord {
    const r = this.sessions.get(id);
    if (!r) throw new Error(`unknown session "${id}"`);
    return r;
  }
}

function describeCause(ev: SessionEvent): string {
  switch (ev.kind) {
    case 'hook':
      return `hook:${ev.event}`;
    case 'exit':
      return `exit:${ev.code}`;
    default:
      return ev.kind;
  }
}

import { describe, it, expect, beforeEach } from 'vitest';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { SessionManager, PtyLike } from './session-manager';
import { transition, SessionStatus } from './state-machine';
import { ContributionRegistry } from '../extensibility/registry';
import { LogSink, createLogger } from '../log/logger';

// ---- fakes ------------------------------------------------------------------
function fakeRegistry(): ContributionRegistry {
  const r = new ContributionRegistry();
  r.register('provider-adapter', {
    manifest: { id: 'fake', displayName: 'Fake', version: '0', capabilities: ['sessions.spawn'] },
    buildSpawn: (o) => ({ command: 'fake-cli', args: o.resumeSessionId ? ['--resume', o.resumeSessionId] : [], env: {} }),
  });
  return r;
}

class FakePtys implements PtyLike {
  spawned: Array<{ id: string; command: string; args: string[] }> = [];
  exitHandlers = new Map<string, (code: number) => void>();
  removed: string[] = [];
  spawn(opts: { id: string; command: string; args: string[] }) {
    this.spawned.push(opts);
    return {
      pid: 1000 + this.spawned.length,
      onExit: (l: (code: number) => void) => {
        this.exitHandlers.set(opts.id, l);
        return () => {};
      },
      kill: () => this.exitHandlers.get(opts.id)?.(0),
    };
  }
  remove(id: string): void {
    this.removed.push(id);
    this.exitHandlers.get(id)?.(0);
  }
}

let dir: string;
let ptys: FakePtys;
let mgr: SessionManager;
beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'sb-sm-'));
  ptys = new FakePtys();
  const sink = new LogSink({ dir });
  mgr = new SessionManager(fakeRegistry(), ptys, createLogger(sink, 'sessions'), dir);
});

const identity = { title: 't', folder: 'C:/tmp/x', providerId: 'fake' };

// ---- the REAL recorded work cycle from the S-06 spike run -------------------
// spike/findings/artifacts/s06/transitions.json: SessionStart ->
// UserPromptSubmit -> Notification(permission_prompt) -> Stop
const S06_REAL_CYCLE = [
  { ev: { kind: 'hook', event: 'SessionStart' } as const, expect: 'starting' },
  { ev: { kind: 'hook', event: 'UserPromptSubmit' } as const, expect: 'working' },
  {
    ev: { kind: 'hook', event: 'Notification', notificationType: 'permission_prompt', message: 'Claude needs your permission' } as const,
    expect: 'needs-permission',
  },
  { ev: { kind: 'hook', event: 'Stop' } as const, expect: 'done' },
];

describe('state machine vs the recorded real cycle (S-06 artifact)', () => {
  it('replays the spike transitions exactly', () => {
    let status: SessionStatus = 'starting';
    for (const step of S06_REAL_CYCLE) {
      status = transition(status, step.ev).status;
      expect(status).toBe(step.expect);
    }
  });

  it('SubagentStop is transient; unknown hooks never transition', () => {
    expect(transition('working', { kind: 'hook', event: 'SubagentStop' })).toMatchObject({
      changed: false,
      note: 'subagent-done',
    });
    expect(transition('working', { kind: 'hook', event: 'FutureThing' })).toMatchObject({
      changed: false,
      note: 'unknown-hook:FutureThing',
    });
  });

  it('exit codes: 0 -> done, nonzero -> crashed, after done -> done', () => {
    expect(transition('working', { kind: 'exit', code: 1 }).status).toBe('crashed');
    expect(transition('working', { kind: 'exit', code: 0 }).status).toBe('done');
    expect(transition('done', { kind: 'exit', code: -1073741510 }).status).toBe('done');
  });

  it('permission hold/resolve (the E2-05+ authority path)', () => {
    expect(transition('working', { kind: 'permission-held' }).status).toBe('needs-permission');
    expect(transition('needs-permission', { kind: 'permission-resolved' }).status).toBe('working');
  });
});

describe('SessionManager (done-when: observable transitions through the cycle)', () => {
  it('create -> real cycle -> transitions logged and queryable', () => {
    const seen: string[] = [];
    mgr.onStatusChange((c) => seen.push(`${c.from}->${c.to}`));
    const s = mgr.create(identity);
    for (const step of S06_REAL_CYCLE) mgr.apply(s.id, step.ev);

    expect(mgr.get(s.id)!.status).toBe('done');
    const t = mgr.transitions(s.id);
    expect(t.map((x) => x.to)).toEqual(['working', 'needs-permission', 'done']);
    expect(t.every((x) => x.sessionId === s.id)).toBe(true);
    expect(seen).toEqual(['starting->working', 'working->needs-permission', 'needs-permission->done']);
    // and the log file carries it, sessionId-filterable (E1-05 contract)
    const lines = fs
      .readFileSync(path.join(dir, 'switchboard.log'), 'utf8')
      .trim()
      .split('\n')
      .map((l) => JSON.parse(l))
      .filter((r) => r.sessionId === s.id && r.msg === 'session status');
    expect(lines.map((r) => r.to)).toEqual(['working', 'needs-permission', 'done']);
  });

  it('kill flips to done via exit(0); crash via nonzero', () => {
    const a = mgr.create(identity);
    mgr.kill(a.id);
    expect(mgr.get(a.id)!.status).toBe('done');

    const b = mgr.create(identity);
    ptys.exitHandlers.get(b.id)!(1);
    expect(mgr.get(b.id)!.status).toBe('crashed');
  });

  it('restart preserves identity and passes the native id as resume', () => {
    const a = mgr.create(identity);
    mgr.setNativeSessionId(a.id, 'native-9');
    const b = mgr.restart(a.id);
    expect(b.id).not.toBe(a.id);
    expect(b.identity).toEqual(identity);
    const spawn = ptys.spawned.at(-1)!;
    expect(spawn.args).toEqual(['--resume', 'native-9']);
    expect(mgr.get(a.id)).toBeUndefined();
  });

  it('late events for removed sessions are dropped silently', () => {
    expect(() => mgr.apply('ghost', { kind: 'hook', event: 'Stop' })).not.toThrow();
  });
});

// Workspace store (P1-E2-04, §5.25/§7): the single persisted picture of the
// workspace — session records (identity, layout slot, provider-native id for
// resume) and window geometry with a display fingerprint. Restore-on-launch
// yields SUSPENDED session records; actual relaunch is resume-on-focus
// (§5.25) — the UI (E3) calls resumeSuspended when a card is touched.
//
// Persistence rules: tolerant load (corrupt file -> backed aside, fresh
// start — never crash on our own state), atomic save (tmp + rename),
// debounced save-soon for churny callers.
import fs from 'fs';
import path from 'path';
import { Rectangle } from 'electron';
import { SessionIdentity } from '../sessions/session-manager';
import { WindowState, mergeState, isOnAnyDisplay } from '../window-state';

export interface PersistedSession {
  id: string;
  identity: SessionIdentity;
  layoutSlot: number;
  nativeSessionId?: string;
  suspendedAt: string;
}

export interface PersistedWindow extends WindowState {
  displayFingerprint: string;
}

export interface WorkspaceState {
  version: 1;
  sessions: PersistedSession[];
  window: PersistedWindow | null;
}

const EMPTY: WorkspaceState = { version: 1, sessions: [], window: null };

/** Stable identity for a display arrangement (§7). */
export function displayFingerprint(workAreas: Rectangle[]): string {
  return workAreas
    .map((a) => `${a.x},${a.y},${a.width},${a.height}`)
    .sort()
    .join('|');
}

export class WorkspaceStore {
  private state: WorkspaceState = EMPTY;
  private saveTimer: NodeJS.Timeout | null = null;

  constructor(private readonly file: string) {}

  load(): WorkspaceState {
    try {
      const raw = JSON.parse(fs.readFileSync(this.file, 'utf8')) as Partial<WorkspaceState>;
      this.state = {
        version: 1,
        sessions: Array.isArray(raw.sessions) ? raw.sessions.filter(isSaneSession) : [],
        window: sanitizeWindow(raw.window),
      };
    } catch (err) {
      // corrupt/missing: back the corpse aside (post-mortem material), start fresh
      if (fs.existsSync(this.file)) {
        try {
          fs.copyFileSync(this.file, `${this.file}.corrupt`);
        } catch {
          /* best-effort */
        }
      }
      this.state = { ...EMPTY, sessions: [] };
      void err;
    }
    return this.snapshot();
  }

  snapshot(): WorkspaceState {
    return JSON.parse(JSON.stringify(this.state)) as WorkspaceState;
  }

  upsertSession(s: PersistedSession): void {
    const i = this.state.sessions.findIndex((x) => x.id === s.id);
    if (i >= 0) this.state.sessions[i] = s;
    else this.state.sessions.push(s);
    this.saveSoon();
  }

  removeSession(id: string): void {
    this.state.sessions = this.state.sessions.filter((x) => x.id !== id);
    this.saveSoon();
  }

  setWindow(w: PersistedWindow): void {
    this.state.window = w;
    this.saveSoon();
  }

  /**
   * Geometry to restore for the current display arrangement. A saved position
   * on a missing display rescues to centered-on-primary (bounds: null).
   */
  restoreWindow(currentWorkAreas: Rectangle[]): WindowState {
    const w = this.state.window;
    if (!w) return { bounds: null, isMaximized: false };
    const sameArrangement = w.displayFingerprint === displayFingerprint(currentWorkAreas);
    if (w.bounds && (sameArrangement || isOnAnyDisplay(w.bounds, currentWorkAreas))) {
      return { bounds: w.bounds, isMaximized: w.isMaximized };
    }
    return { bounds: null, isMaximized: w.isMaximized }; // rescue, keep maximized
  }

  save(): void {
    if (this.saveTimer) {
      clearTimeout(this.saveTimer);
      this.saveTimer = null;
    }
    const tmp = `${this.file}.tmp`;
    try {
      fs.mkdirSync(path.dirname(this.file), { recursive: true });
      fs.writeFileSync(tmp, JSON.stringify(this.state, null, 2));
      fs.renameSync(tmp, this.file);
    } catch {
      /* persistence is best-effort — never take the app down (fail-open) */
    }
  }

  saveSoon(): void {
    if (this.saveTimer) clearTimeout(this.saveTimer);
    this.saveTimer = setTimeout(() => this.save(), 500);
  }
}

function isSaneSession(s: unknown): s is PersistedSession {
  const x = s as Partial<PersistedSession>;
  return (
    typeof x?.id === 'string' &&
    typeof x?.identity?.folder === 'string' &&
    typeof x?.identity?.providerId === 'string' &&
    typeof x?.layoutSlot === 'number'
  );
}

function sanitizeWindow(w: unknown): PersistedWindow | null {
  if (typeof w !== 'object' || w === null) return null;
  const fp = (w as { displayFingerprint?: unknown }).displayFingerprint;
  if (typeof fp !== 'string') return null;
  const merged = mergeState(w);
  return { ...merged, displayFingerprint: fp };
}

import { describe, it, expect, beforeEach, vi } from 'vitest';
import fs from 'fs';
import os from 'os';
import path from 'path';

vi.mock('electron', () => ({
  app: { getPath: () => '/tmp' },
  screen: { getAllDisplays: () => [] },
  BrowserWindow: class {},
}));

import { WorkspaceStore, displayFingerprint, PersistedSession } from './store';

let dir: string;
let file: string;
beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'sb-ws-'));
  file = path.join(dir, 'workspace.json');
});

const sess = (id: string, slot = 0): PersistedSession => ({
  id,
  identity: { title: id, folder: `C:/tmp/${id}`, providerId: 'claude-code' },
  layoutSlot: slot,
  nativeSessionId: `native-${id}`,
  suspendedAt: '2026-07-19T00:00:00.000Z',
});

const primary = { x: 0, y: 0, width: 1920, height: 1040 };
const left = { x: -1920, y: 0, width: 1920, height: 1040 };

describe('WorkspaceStore (done-when: quit -> relaunch reproduces exactly)', () => {
  it('save + fresh load round-trips sessions and window byte-exactly', () => {
    const a = new WorkspaceStore(file);
    a.load();
    a.upsertSession(sess('one', 0));
    a.upsertSession(sess('two', 3));
    a.setWindow({
      bounds: { x: 10, y: 20, width: 1200, height: 800 },
      isMaximized: false,
      displayFingerprint: displayFingerprint([primary, left]),
    });
    a.save();

    const b = new WorkspaceStore(file); // "relaunch"
    const restored = b.load();
    expect(restored).toEqual(a.snapshot());
    expect(restored.sessions.map((s) => s.id)).toEqual(['one', 'two']);
    expect(restored.sessions[1].layoutSlot).toBe(3);
    expect(restored.sessions[1].nativeSessionId).toBe('native-two');
  });

  it('upsert replaces by id; remove drops', () => {
    const st = new WorkspaceStore(file);
    st.load();
    st.upsertSession(sess('a', 0));
    st.upsertSession({ ...sess('a', 5) });
    expect(st.snapshot().sessions).toHaveLength(1);
    expect(st.snapshot().sessions[0].layoutSlot).toBe(5);
    st.removeSession('a');
    expect(st.snapshot().sessions).toHaveLength(0);
  });

  it('corrupt file: backed aside, fresh start, no throw', () => {
    fs.writeFileSync(file, '{not json!!');
    const st = new WorkspaceStore(file);
    const s = st.load();
    expect(s.sessions).toEqual([]);
    expect(fs.existsSync(`${file}.corrupt`)).toBe(true);
  });

  it('garbage session entries are filtered on load', () => {
    fs.writeFileSync(
      file,
      JSON.stringify({ version: 1, sessions: [sess('ok'), { id: 42 }, 'x'], window: null })
    );
    const st = new WorkspaceStore(file);
    expect(st.load().sessions.map((s) => s.id)).toEqual(['ok']);
  });
});

describe('missing-display rescue (done-when part 2)', () => {
  it('same arrangement: exact geometry restored', () => {
    const st = new WorkspaceStore(file);
    st.load();
    st.setWindow({
      bounds: { x: -1800, y: 50, width: 800, height: 600 },
      isMaximized: false,
      displayFingerprint: displayFingerprint([primary, left]),
    });
    const w = st.restoreWindow([primary, left]);
    expect(w.bounds).toEqual({ x: -1800, y: 50, width: 800, height: 600 });
  });

  it('display gone + bounds off every remaining display: rescue to centered, keep maximized', () => {
    const st = new WorkspaceStore(file);
    st.load();
    st.setWindow({
      bounds: { x: -1800, y: 50, width: 800, height: 600 }, // on the left display
      isMaximized: true,
      displayFingerprint: displayFingerprint([primary, left]),
    });
    const w = st.restoreWindow([primary]); // left display unplugged
    expect(w.bounds).toBeNull();
    expect(w.isMaximized).toBe(true);
  });

  it('arrangement changed but bounds still visible: keep them', () => {
    const st = new WorkspaceStore(file);
    st.load();
    st.setWindow({
      bounds: { x: 100, y: 100, width: 800, height: 600 },
      isMaximized: false,
      displayFingerprint: displayFingerprint([primary, left]),
    });
    const w = st.restoreWindow([primary]);
    expect(w.bounds).toEqual({ x: 100, y: 100, width: 800, height: 600 });
  });
});

describe('fingerprint stability', () => {
  it('is order-independent', () => {
    expect(displayFingerprint([primary, left])).toBe(displayFingerprint([left, primary]));
  });
});

