import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'fs';
import http from 'http';
import os from 'os';
import path from 'path';
import { HookListener } from './hook-listener';
import { LogSink, createLogger } from '../log/logger';
import { SessionEvent } from '../sessions/state-machine';

let dir: string;
let listener: HookListener;
let applied: Array<{ sessionId: string; ev: SessionEvent }>;
let nativeIds: Array<{ sessionId: string; nativeId: string }>;
let port: number;

beforeEach(async () => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'sb-hooks-'));
  applied = [];
  nativeIds = [];
  listener = new HookListener({
    stateDir: dir,
    log: createLogger(new LogSink({ dir }), 'hooks'),
    manager: {
      apply: (sessionId, ev) => applied.push({ sessionId, ev }),
      setNativeSessionId: (sessionId, nativeId) => nativeIds.push({ sessionId, nativeId }),
    },
  });
  port = await listener.start();
});

afterEach(() => listener.stop());

function post(body: string, headers: Record<string, string>, host?: string): Promise<number> {
  return new Promise((resolve, reject) => {
    const req = http.request(
      {
        host: '127.0.0.1',
        port,
        path: '/hook',
        method: 'POST',
        headers: { 'content-type': 'application/json', ...(host ? { host } : {}), ...headers },
      },
      (res) => {
        res.resume();
        res.on('end', () => resolve(res.statusCode ?? 0));
      }
    );
    req.on('error', reject);
    req.end(body);
  });
}

function tokenFor(sessionId: string): string {
  const { tokenPath } = listener.registerSession(sessionId);
  return fs.readFileSync(tokenPath, 'utf8');
}

describe('§5.29 floor (done-when: invalid requests rejected and logged)', () => {
  it('401 without a valid token; nothing reaches the manager', async () => {
    expect(await post('{}', {})).toBe(401);
    expect(await post('{}', { 'x-switchboard-token': 'wrong' })).toBe(401);
    expect(applied).toHaveLength(0);
    const log = fs.readFileSync(path.join(dir, 'switchboard.log'), 'utf8');
    expect(log).toContain('invalid token');
  });

  it('403 for non-loopback Host even with a valid token', async () => {
    const t = tokenFor('s1');
    expect(await post('{}', { 'x-switchboard-token': t }, 'evil.example')).toBe(403);
    expect(applied).toHaveLength(0);
  });
});

describe('event routing', () => {
  it('maps hook payloads to session events and captures the native id', async () => {
    const t = tokenFor('s1');
    const status = await post(
      JSON.stringify({
        hook_event_name: 'Notification',
        notification_type: 'permission_prompt',
        message: 'Claude needs your permission',
        session_id: 'native-abc',
      }),
      { 'x-switchboard-token': t }
    );
    expect(status).toBe(200);
    await new Promise((r) => setTimeout(r, 50)); // ingest happens post-ack
    expect(nativeIds).toEqual([{ sessionId: 's1', nativeId: 'native-abc' }]);
    expect(applied).toHaveLength(1);
    expect(applied[0].ev).toMatchObject({
      kind: 'hook',
      event: 'Notification',
      notificationType: 'permission_prompt',
    });
  });

  it('tokens are per-session and revocable', async () => {
    const t1 = tokenFor('s1');
    listener.unregisterSession('s1');
    expect(await post('{}', { 'x-switchboard-token': t1 })).toBe(401);
  });

  it('unparseable bodies are logged, not fatal', async () => {
    const t = tokenFor('s1');
    expect(await post('{{{nope', { 'x-switchboard-token': t })).toBe(200);
    await new Promise((r) => setTimeout(r, 50));
    expect(applied).toHaveLength(0);
  });
});

describe('buildHookSettings', () => {
  it('produces a valid injectable hook config with token-by-path (S-03)', () => {
    const settings = listener.buildHookSettings('s9') as {
      hooks: Record<string, Array<{ hooks: Array<{ command: string; timeout: number }> }>>;
    };
    for (const ev of ['SessionStart', 'UserPromptSubmit', 'Notification', 'SubagentStop', 'Stop']) {
      expect(settings.hooks[ev]).toHaveLength(1);
      const h = settings.hooks[ev][0].hooks[0];
      expect(h.timeout).toBe(10);
      expect(h.command).toContain('hook-forwarder.cjs');
      expect(h.command).toContain('hook-token'); // path, not the token itself
      expect(h.command).not.toMatch(/[0-9a-f]{32}/); // no raw token on argv
    }
    expect(fs.existsSync(path.join(dir, 'hook-forwarder.cjs'))).toBe(true);
    expect(fs.existsSync(path.join(dir, 's9', 'hook-token'))).toBe(true);
  });
});

// P1-E2-05 done-when check (local only — needs a logged-in claude CLI):
// session status flips from hook events ALONE through a real CLI run, and
// invalid requests are rejected. Run: npm run check:hooks
import { execFileSync } from 'child_process';
import fs from 'fs';
import http from 'http';
import os from 'os';
import path from 'path';
import { HookListener } from './hook-listener';
import { SessionManager, PtyLike } from '../sessions/session-manager';
import { ContributionRegistry } from '../extensibility/registry';
import { claudeAdapter, resolveCliPath } from '../providers/claude';
import { LogSink, createLogger } from '../log/logger';

const stateDir = fs.mkdtempSync(path.join(os.tmpdir(), 'sb-hook-check-'));
const workDir = fs.mkdtempSync(path.join(os.tmpdir(), 'sb-hook-check-work-'));

// fake PTY: the real CLI runs via child_process below; the manager just needs
// a session record to route hook events into
const fakePty: PtyLike = {
  spawn: () => ({ pid: 0, onExit: () => () => {}, kill: () => {} }),
  remove: () => {},
};

async function main(): Promise<number> {
  const sink = new LogSink({ dir: stateDir });
  const registry = new ContributionRegistry();
  registry.register('provider-adapter', claudeAdapter);
  const manager = new SessionManager(registry, fakePty, createLogger(sink, 'sessions'), stateDir);
  const listener = new HookListener({
    stateDir,
    manager,
    log: createLogger(sink, 'hooks'),
  });
  const port = await listener.start();

  // negative tests first (§5.29 floor)
  const noToken = await rawPost(port, '{}', {});
  const badHost = await rawPost(port, '{}', { host: 'evil.example' });
  console.log(`[hook-check] no-token=${noToken} bad-host=${badHost}`);

  // create the session record and its injected hook settings
  const record = manager.create(
    { title: 'hook-check', folder: workDir, providerId: 'claude-code' },
    {}
  );
  const settings = listener.buildHookSettings(record.id);
  const settingsPath = path.join(stateDir, 'inject-settings.json');
  fs.writeFileSync(settingsPath, JSON.stringify(settings));

  // real CLI run with ONLY hook wiring — no transcript polling anywhere
  const cli = resolveCliPath()!;
  const isCmd = process.platform === 'win32' && cli.toLowerCase().endsWith('.cmd');
  const env = { ...process.env };
  delete env.ELECTRON_RUN_AS_NODE;
  delete env.ELECTRON_NO_ATTACH_CONSOLE;
  console.log('[hook-check] running claude -p with injected hooks...');
  execFileSync(
    isCmd ? 'cmd.exe' : cli,
    [...(isCmd ? ['/c', cli] : []), '--settings', settingsPath, '-p', 'Reply with exactly: OK'],
    { cwd: workDir, encoding: 'utf8', timeout: 180000, env }
  );

  await sleep(1000); // let trailing hook posts land
  const t = manager.transitions(record.id);
  console.log(`[hook-check] transitions: ${t.map((x) => `${x.from}->${x.to} (${x.cause})`).join(', ')}`);
  const seq = t.map((x) => x.to);
  const ok =
    noToken === 401 &&
    badHost === 403 &&
    seq.includes('working') &&
    seq[seq.length - 1] === 'done' &&
    manager.get(record.id)!.nativeSessionId !== undefined;
  console.log(
    `[hook-check] final=${manager.get(record.id)!.status} nativeId=${manager.get(record.id)!.nativeSessionId}`
  );
  console.log(ok ? '[hook-check] PASS' : '[hook-check] FAIL');
  listener.stop();
  return ok ? 0 : 1;
}

function rawPost(port: number, body: string, headers: Record<string, string>): Promise<number> {
  return new Promise((resolve) => {
    const req = http.request(
      { host: '127.0.0.1', port, path: '/hook', method: 'POST', headers },
      (res) => {
        res.resume();
        res.on('end', () => resolve(res.statusCode ?? 0));
      }
    );
    req.on('error', () => resolve(-1));
    req.end(body);
  });
}

function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

main().then(
  (c) => process.exit(c),
  (err) => {
    console.error('[hook-check] ERROR', err);
    process.exit(1);
  }
);

// TranscriptWatcher (P1-E2-06): tolerant live tailer over Claude Code's JSONL
// transcripts, per the S-04/S-05 findings:
//   - transcripts appear on FIRST PROMPT, not spawn — absence is normal
//   - discovery = new-file detection VALIDATED against cwd/sessionId (the
//     adoption race is real; slug math only narrows the scan)
//   - recursive scan: subagent transcripts live nested at
//     <slug>/<session-uuid>/subagents/agent-<id>.jsonl with a .meta.json
//   - tolerant reader: malformed/unknown lines counted, never thrown
//   - transcript is TELEMETRY authority (tokens, tools, files); status
//     authority is hooks (E2-05)
import fs from 'fs';
import path from 'path';
import { Logger } from '../log/logger';

export interface UsageTotals {
  input: number;
  output: number;
  cacheRead: number;
  cacheCreate: number;
}

export interface TranscriptSnapshot {
  sessionId: string;
  bound: boolean;
  nativeSessionId?: string;
  usage: UsageTotals;
  lines: number;
  malformed: number;
  toolsSeen: string[];
  filesTouched: string[];
  subagents: Array<{ agentId: string; agentType?: string; description?: string }>;
  lastActivityAt: string | null;
}

interface WatchedSession {
  sessionId: string;
  cwd: string;
  nativeSessionId?: string;
  boundFile: string | null;
  tails: Map<string, { offset: number; buf: string }>;
  snap: TranscriptSnapshot;
}

export interface TranscriptWatcherOptions {
  projectsRoot: string;
  log: Logger;
  pollMs?: number;
}

export function slugForCwd(cwd: string): string {
  return cwd.replace(/[\\/:. ]/g, '-');
}

export class TranscriptWatcher {
  private readonly sessions = new Map<string, WatchedSession>();
  private readonly known = new Set<string>(); // files existing before any watch
  private readonly listeners = new Set<(s: TranscriptSnapshot) => void>();
  private timer: NodeJS.Timeout | null = null;

  constructor(private readonly opts: TranscriptWatcherOptions) {
    for (const f of this.scan()) this.known.add(f);
  }

  watch(sessionId: string, session: { cwd: string; nativeSessionId?: string }): void {
    this.sessions.set(sessionId, {
      sessionId,
      cwd: session.cwd,
      nativeSessionId: session.nativeSessionId,
      boundFile: null,
      tails: new Map(),
      snap: {
        sessionId,
        bound: false,
        usage: { input: 0, output: 0, cacheRead: 0, cacheCreate: 0 },
        lines: 0,
        malformed: 0,
        toolsSeen: [],
        filesTouched: [],
        subagents: [],
        lastActivityAt: null,
      },
    });
    this.ensurePolling();
  }

  /** Late-arriving native id (from hooks) tightens binding validation. */
  setNativeSessionId(sessionId: string, nativeId: string): void {
    const w = this.sessions.get(sessionId);
    if (w) w.nativeSessionId = nativeId;
  }

  unwatch(sessionId: string): void {
    this.sessions.delete(sessionId);
    if (this.sessions.size === 0 && this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  snapshot(sessionId: string): TranscriptSnapshot | undefined {
    const w = this.sessions.get(sessionId);
    return w ? { ...w.snap, toolsSeen: [...w.snap.toolsSeen], filesTouched: [...w.snap.filesTouched], subagents: [...w.snap.subagents] } : undefined;
  }

  onUpdate(l: (s: TranscriptSnapshot) => void): () => void {
    this.listeners.add(l);
    return () => this.listeners.delete(l);
  }

  stop(): void {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
  }

  // --- internals -------------------------------------------------------------

  private ensurePolling(): void {
    if (this.timer) return;
    this.timer = setInterval(() => this.poll(), this.opts.pollMs ?? 100);
    this.timer.unref?.();
  }

  private scan(root = this.opts.projectsRoot, depth = 0, acc: string[] = []): string[] {
    if (depth > 4) return acc;
    let names: string[];
    try {
      names = fs.readdirSync(root);
    } catch {
      return acc;
    }
    for (const name of names) {
      const full = path.join(root, name);
      let st: fs.Stats;
      try {
        st = fs.statSync(full);
      } catch {
        continue;
      }
      if (st.isDirectory()) this.scan(full, depth + 1, acc);
      else if (name.endsWith('.jsonl')) acc.push(full);
    }
    return acc;
  }

  private poll(): void {
    const files = this.scan();
    for (const w of this.sessions.values()) {
      for (const full of files) {
        if (this.known.has(full) || w.tails.has(full)) continue;
        if (this.claim(w, full)) w.tails.set(full, { offset: 0, buf: '' });
      }
      for (const [full, tail] of w.tails) this.drain(w, full, tail);
    }
  }

  /** Bind only files that verifiably belong to this session (the race fix). */
  private claim(w: WatchedSession, full: string): boolean {
    const rel = path.relative(this.opts.projectsRoot, full);
    const inSlug = rel.split(path.sep)[0] === slugForCwd(w.cwd);
    if (!inSlug) return false;
    const isSubagent = rel.includes('subagents');
    if (isSubagent) {
      // subagent files belong to us if nested under our bound session uuid
      return !!w.boundFile && rel.includes(path.basename(w.boundFile, '.jsonl'));
    }
    if (w.boundFile) return false; // one main transcript per session
    // peek the first parseable line: cwd must match; sessionId must match the
    // native id when we know it
    const head = this.readHead(full);
    if (!head) return false;
    if (typeof head.cwd === 'string' && path.resolve(head.cwd) !== path.resolve(w.cwd)) return false;
    if (w.nativeSessionId && head.sessionId !== w.nativeSessionId) return false;
    w.boundFile = full;
    w.snap.bound = true;
    w.snap.nativeSessionId = typeof head.sessionId === 'string' ? head.sessionId : undefined;
    this.opts.log.info('transcript bound', { sessionId: w.sessionId, file: path.basename(full) });
    // pick up the meta sidecar if this session later spawns agents (S-05)
    return true;
  }

  private readHead(full: string): { cwd?: unknown; sessionId?: unknown } | null {
    try {
      const fd = fs.openSync(full, 'r');
      const buf = Buffer.alloc(4096);
      const n = fs.readSync(fd, buf, 0, buf.length, 0);
      fs.closeSync(fd);
      const firstLine = buf.toString('utf8', 0, n).split('\n')[0];
      return JSON.parse(firstLine) as { cwd?: unknown; sessionId?: unknown };
    } catch {
      return null;
    }
  }

  private drain(w: WatchedSession, full: string, tail: { offset: number; buf: string }): void {
    let st: fs.Stats;
    try {
      st = fs.statSync(full);
    } catch {
      return;
    }
    if (st.size <= tail.offset) return;
    let chunk: Buffer;
    try {
      const fd = fs.openSync(full, 'r');
      chunk = Buffer.alloc(st.size - tail.offset);
      fs.readSync(fd, chunk, 0, chunk.length, tail.offset);
      fs.closeSync(fd);
    } catch {
      return;
    }
    tail.offset = st.size;
    tail.buf += chunk.toString('utf8');
    let nl: number;
    let touched = false;
    while ((nl = tail.buf.indexOf('\n')) >= 0) {
      const line = tail.buf.slice(0, nl);
      tail.buf = tail.buf.slice(nl + 1);
      if (!line.trim()) continue;
      w.snap.lines++;
      touched = true;
      let e: Record<string, unknown>;
      try {
        e = JSON.parse(line) as Record<string, unknown>;
      } catch {
        w.snap.malformed++;
        continue;
      }
      this.absorb(w, full, e);
    }
    if (touched) {
      w.snap.lastActivityAt = new Date().toISOString();
      for (const l of this.listeners) l(this.snapshot(w.sessionId)!);
    }
  }

  private absorb(w: WatchedSession, full: string, e: Record<string, unknown>): void {
    if (full === w.boundFile && typeof e.sessionId === 'string' && !w.snap.nativeSessionId) {
      w.snap.nativeSessionId = e.sessionId;
    }
    const message = e.message as { usage?: Record<string, number>; content?: unknown } | undefined;
    const usage = message?.usage;
    if (usage) {
      w.snap.usage.input += usage.input_tokens ?? 0;
      w.snap.usage.output += usage.output_tokens ?? 0;
      w.snap.usage.cacheRead += usage.cache_read_input_tokens ?? 0;
      w.snap.usage.cacheCreate += usage.cache_creation_input_tokens ?? 0;
    }
    const content = Array.isArray(message?.content) ? message.content : [];
    for (const c of content as Array<{ type?: string; name?: string; input?: Record<string, unknown> }>) {
      if (c?.type === 'tool_use') {
        if (c.name && !w.snap.toolsSeen.includes(c.name)) w.snap.toolsSeen.push(c.name);
        const fp = c.input?.file_path ?? c.input?.path ?? c.input?.notebook_path;
        if (typeof fp === 'string' && !w.snap.filesTouched.includes(fp)) {
          w.snap.filesTouched.push(fp);
        }
        if ((c.name === 'Agent' || c.name === 'Task') && full === w.boundFile) {
          this.pickupSubagentMeta(w);
        }
      }
    }
  }

  /** Read meta sidecars for any agent files under our session dir (S-05). */
  private pickupSubagentMeta(w: WatchedSession): void {
    if (!w.boundFile) return;
    const dir = path.join(path.dirname(w.boundFile), path.basename(w.boundFile, '.jsonl'), 'subagents');
    let names: string[];
    try {
      names = fs.readdirSync(dir);
    } catch {
      return;
    }
    for (const name of names) {
      if (!name.endsWith('.meta.json')) continue;
      const agentId = name.replace(/^agent-/, '').replace(/\.meta\.json$/, '');
      if (w.snap.subagents.some((s) => s.agentId === agentId)) continue;
      try {
        const meta = JSON.parse(fs.readFileSync(path.join(dir, name), 'utf8')) as {
          agentType?: string;
          description?: string;
        };
        w.snap.subagents.push({ agentId, agentType: meta.agentType, description: meta.description });
      } catch {
        w.snap.subagents.push({ agentId });
      }
    }
  }
}

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { TranscriptWatcher, slugForCwd } from './watcher';
import { LogSink, createLogger } from '../log/logger';

let root: string;
let cwd: string;
let watcher: TranscriptWatcher;

beforeEach(() => {
  root = fs.mkdtempSync(path.join(os.tmpdir(), 'sb-tw-root-'));
  cwd = 'C:/tmp/tw-project';
  watcher = new TranscriptWatcher({
    projectsRoot: root,
    log: createLogger(new LogSink({ dir: root }), 'transcripts'),
    pollMs: 25,
  });
});

afterEach(() => watcher.stop());

function projectDir(): string {
  const d = path.join(root, slugForCwd(cwd));
  fs.mkdirSync(d, { recursive: true });
  return d;
}

function writeLines(file: string, lines: string[]): void {
  fs.appendFileSync(file, lines.map((l) => l + '\n').join(''));
}

const entry = (over: Record<string, unknown> = {}) =>
  JSON.stringify({ type: 'assistant', sessionId: 'native-1', cwd, timestamp: new Date().toISOString(), ...over });

function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

describe('binding validation (the S-04 race fix)', () => {
  it('binds a transcript whose head matches cwd, tolerating late creation', async () => {
    watcher.watch('s1', { cwd });
    await sleep(80); // transcript does not exist yet — must not blow up
    expect(watcher.snapshot('s1')!.bound).toBe(false);

    const file = path.join(projectDir(), 'native-1.jsonl');
    writeLines(file, [entry()]);
    await sleep(120);
    const snap = watcher.snapshot('s1')!;
    expect(snap.bound).toBe(true);
    expect(snap.nativeSessionId).toBe('native-1');
  });

  it('refuses a transcript from another cwd in the same window', async () => {
    watcher.watch('s1', { cwd });
    const file = path.join(projectDir(), 'imposter.jsonl');
    writeLines(file, [entry({ cwd: 'C:/somewhere/else' })]);
    await sleep(120);
    expect(watcher.snapshot('s1')!.bound).toBe(false);
  });

  it('refuses a mismatched sessionId when the native id is known', async () => {
    watcher.watch('s1', { cwd, nativeSessionId: 'expected-id' });
    writeLines(path.join(projectDir(), 'other.jsonl'), [entry({ sessionId: 'different-id' })]);
    await sleep(120);
    expect(watcher.snapshot('s1')!.bound).toBe(false);
  });
});

describe('live usage totals + tolerant reader (the done-when)', () => {
  it('token counts update live across appends; malformed lines never crash', async () => {
    watcher.watch('s1', { cwd });
    const file = path.join(projectDir(), 'native-1.jsonl');
    writeLines(file, [entry({ message: { usage: { input_tokens: 5, output_tokens: 10 } } })]);
    await sleep(120);
    expect(watcher.snapshot('s1')!.usage).toMatchObject({ input: 5, output: 10 });

    const updates: number[] = [];
    const off = watcher.onUpdate((s) => updates.push(s.usage.output));
    writeLines(file, [
      'garbage {{{ not json',
      entry({ type: 'unknown-future-type' }),
      entry({
        message: {
          usage: { output_tokens: 7, cache_read_input_tokens: 100 },
          content: [{ type: 'tool_use', name: 'Write', input: { file_path: 'C:/tmp/tw-project/x.txt' } }],
        },
      }),
    ]);
    await sleep(120);
    off();
    const snap = watcher.snapshot('s1')!;
    expect(snap.usage).toMatchObject({ input: 5, output: 17, cacheRead: 100 });
    expect(snap.malformed).toBe(1);
    expect(snap.lines).toBe(4);
    expect(snap.toolsSeen).toContain('Write');
    expect(snap.filesTouched).toContain('C:/tmp/tw-project/x.txt');
    expect(updates.length).toBeGreaterThan(0);
    expect(snap.lastActivityAt).not.toBeNull();
  });
});

describe('subagent visibility (S-05 layout)', () => {
  it('tails nested agent files and reads meta sidecars', async () => {
    watcher.watch('s1', { cwd });
    const file = path.join(projectDir(), 'native-1.jsonl');
    writeLines(file, [entry()]);
    await sleep(100);

    const subDir = path.join(projectDir(), 'native-1', 'subagents');
    fs.mkdirSync(subDir, { recursive: true });
    fs.writeFileSync(
      path.join(subDir, 'agent-abc123.meta.json'),
      JSON.stringify({ agentType: 'general-purpose', description: 'count lines' })
    );
    writeLines(path.join(subDir, 'agent-abc123.jsonl'), [
      entry({ isSidechain: true, agentId: 'abc123', message: { usage: { output_tokens: 3 } } }),
    ]);
    // Agent tool_use in the main transcript triggers meta pickup
    writeLines(file, [
      entry({ message: { content: [{ type: 'tool_use', name: 'Agent', input: { description: 'count lines' } }] } }),
    ]);
    await sleep(150);
    const snap = watcher.snapshot('s1')!;
    expect(snap.subagents).toEqual([
      { agentId: 'abc123', agentType: 'general-purpose', description: 'count lines' },
    ]);
    expect(snap.usage.output).toBe(3); // subagent tokens counted
  });
});

describe('pre-existing transcripts are never adopted', () => {
  it('ignores files that existed before the watcher started', async () => {
    const file = path.join(projectDir(), 'old.jsonl');
    writeLines(file, [entry()]);
    const w2 = new TranscriptWatcher({
      projectsRoot: root,
      log: createLogger(new LogSink({ dir: root }), 'transcripts'),
      pollMs: 25,
    });
    w2.watch('s1', { cwd });
    writeLines(file, [entry({ message: { usage: { output_tokens: 99 } } })]);
    await sleep(120);
    expect(w2.snapshot('s1')!.bound).toBe(false);
    expect(w2.snapshot('s1')!.usage.output).toBe(0);
    w2.stop();
  });
});

