// Bug 2 reproduction: through the REAL app path (SessionManager + HookListener
// + PtyService), spawn an interactive session in a folder with its OWN hooks,
// ask a tool-using question, and — crucially — do NOT kill; wait for the turn
// to finish and settle, then print the final status + full transition log.
// If final status is 'working', the stuck-status bug is reproduced.
import fs from 'fs';
import os from 'os';
import path from 'path';
import { HookListener } from '../hooks/hook-listener';
import { SessionManager } from './session-manager';
import { ContributionRegistry } from '../extensibility/registry';
import { claudeAdapter } from '../providers/claude';
import { PtyService } from '../pty/pty-service';
import { LogSink, createLogger } from '../log/logger';

const stateDir = fs.mkdtempSync(path.join(os.tmpdir(), 'sb-repro2-'));
const workDir = fs.mkdtempSync(path.join(os.tmpdir(), 'sb-repro2-work-'));
// give the fixture its OWN hooks (mimics ClaudeMon) + a file to read
fs.mkdirSync(path.join(workDir, '.claude'), { recursive: true });
fs.writeFileSync(
  path.join(workDir, '.claude', 'settings.json'),
  JSON.stringify({ hooks: { PreToolUse: [{ matcher: 'Bash', hooks: [{ type: 'command', command: 'node -e ""' }] }] } })
);
fs.writeFileSync(path.join(workDir, 'readme.txt'), 'hello world line one\n');

/* eslint-disable no-control-regex */
const strip = (s: string) =>
  s
    .replace(/\x1b\][^\x07\x1b]*(\x07|\x1b\\)/g, '')
    .replace(/\x1b\[[0-9;?]*[ -/]*[@-~]/g, '')
    .replace(/[\x00-\x08\x0b-\x1f]/g, '');
/* eslint-enable no-control-regex */

async function main(): Promise<number> {
  const sink = new LogSink({ dir: stateDir });
  const registry = new ContributionRegistry();
  registry.register('provider-adapter', claudeAdapter);
  const ptys = new PtyService();
  const manager = new SessionManager(registry, ptys, createLogger(sink, 'sessions'), stateDir);
  const listener = new HookListener({ stateDir, manager, log: createLogger(sink, 'hooks') });
  await listener.start();

  const record = manager.create(
    { title: 'repro', folder: workDir, providerId: 'claude-code' },
    { settingsFor: (id) => listener.buildHookSettings(id) }
  );
  const pty = ptys.get(record.id)!;
  let screen = '';
  pty.onData((d) => (screen += strip(d)));

  await waitFor(() => /(trust|Accessing|\?\s*for\s*shortcuts)/i.test(screen), 60000, 'startup');
  if (/(trust|Accessing)/i.test(screen) && !/\?\s*for\s*shortcuts/i.test(screen)) {
    pty.write('\r');
    await waitFor(() => /\?\s*for\s*shortcuts/i.test(screen), 30000, 'ready');
  }
  await sleep(1500);
  // a tool-using question, like asking about a project — fires PostToolUse
  // right before Stop
  pty.write('Use the Read tool to read readme.txt and tell me its first line');
  await sleep(900);
  pty.write('\r');

  // wait until the model has answered (mentions the file content), then let
  // ALL hooks settle for several seconds
  await waitFor(() => /hello world line one/i.test(screen), 120000, 'answered').catch(() => {});
  console.log('[repro] model answered; settling 8s for late hooks...');
  await sleep(8000);

  const finalStatus = manager.get(record.id)!.status;
  const transitions = manager.transitions(record.id);
  console.log(`[repro] transitions: ${transitions.map((t) => `${t.from}->${t.to}(${t.cause})`).join(', ')}`);
  console.log(`[repro] FINAL STATUS: ${finalStatus}`);
  console.log(
    finalStatus === 'done'
      ? '[repro] OK — status settled on done'
      : `[repro] BUG REPRODUCED — stuck on "${finalStatus}" after the turn finished`
  );
  manager.kill(record.id);
  ptys.killAll();
  listener.stop();
  return finalStatus === 'done' ? 0 : 2;
}

async function waitFor(cond: () => boolean, timeoutMs: number, label: string): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (cond()) return;
    await sleep(150);
  }
  throw new Error(`timeout waiting for ${label}`);
}
function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

main().then(
  (c) => setTimeout(() => process.exit(c), 500),
  (err) => {
    console.error('[repro] ERROR', err);
    process.exit(1);
  }
);

