// Probe: does pre-setting projects[folder].hasTrustDialogAccepted=true in
// ~/.claude.json make an INTERACTIVE claude session skip the trust dialog?
// Run under electron's node (node-pty ABI): ELECTRON_RUN_AS_NODE=1 electron this.js
const pty = require('C:/Projects/Switchboard.ai/node_modules/node-pty');
const fs = require('fs');
const os = require('os');
const path = require('path');

const cjson = path.join(os.homedir(), '.claude.json');
const fresh = fs.mkdtempSync(path.join(os.tmpdir(), 'trust-probe-'));

function run(label, preTrust) {
  return new Promise((resolve) => {
    if (preTrust) {
      const c = JSON.parse(fs.readFileSync(cjson, 'utf8'));
      c.projects = c.projects || {};
      c.projects[fresh] = { ...(c.projects[fresh] || {}), hasTrustDialogAccepted: true };
      fs.writeFileSync(cjson, JSON.stringify(c, null, 2));
    }
    const env = { ...process.env };
    delete env.ELECTRON_RUN_AS_NODE;
    delete env.ELECTRON_NO_ATTACH_CONSOLE;
    const p = pty.spawn('claude.cmd', [], { name: 'xterm-256color', cols: 120, rows: 30, cwd: fresh, env, useConpty: true });
    let out = '';
    const strip = (s) => s.replace(/\x1b\][^\x07\x1b]*(\x07|\x1b\\)/g, '').replace(/\x1b\[[0-9;?]*[ -/]*[@-~]/g, '').replace(/[\x00-\x1f]/g, '');
    p.onData((d) => (out += strip(d)));
    setTimeout(() => {
      const trustAsked = /trust|Accessing\s*workspace/i.test(out);
      const ready = /\?\s*for\s*shortcuts/i.test(out);
      console.log(`[${label}] trustDialogShown=${trustAsked} readyPrompt=${ready}`);
      try { p.kill(); } catch (_) {}
      resolve();
    }, 9000);
  });
}

(async () => {
  await run('WITHOUT pre-trust', false);
  await run('WITH pre-trust', true);
  process.exit(0);
})();

