// Auto-trust (opt-in, default on): choosing a folder to run an agent in IS
// the trust decision (same premise as the VS Code extension). We pre-set the
// flag Claude Code writes when a user accepts its trust dialog, so the session
// skips that prompt.
//
// Verified: projects are keyed in ~/.claude.json by FORWARD-SLASH path, and
// hasTrustDialogAccepted:true under that key makes an interactive session go
// straight to the composer.
//
// This edits the user's real ~/.claude.json — so: merge (never clobber),
// atomic write (tmp + rename), and fail-open (any error just leaves the trust
// dialog in place, no harm).
import fs from 'fs';
import os from 'os';
import path from 'path';
import { Logger } from '../log/logger';

function claudeConfigPath(): string {
  return path.join(os.homedir(), '.claude.json');
}

/** The key Claude Code uses for a project: absolute path, forward slashes. */
export function projectKey(folder: string): string {
  return path.resolve(folder).replace(/\\/g, '/');
}

/**
 * Ensure `folder` is marked trusted. Returns true if the config now reflects
 * trust (already-trusted or successfully written), false on any failure.
 */
export function ensureFolderTrusted(folder: string, log?: Logger): boolean {
  const file = claudeConfigPath();
  try {
    const raw = fs.readFileSync(file, 'utf8');
    const cfg = JSON.parse(raw) as { projects?: Record<string, Record<string, unknown>> };
    cfg.projects = cfg.projects ?? {};
    const key = projectKey(folder);
    const existing = cfg.projects[key] ?? {};
    if (existing.hasTrustDialogAccepted === true) return true; // already trusted
    cfg.projects[key] = {
      ...existing,
      hasTrustDialogAccepted: true,
      projectOnboardingSeenCount:
        typeof existing.projectOnboardingSeenCount === 'number' ? existing.projectOnboardingSeenCount : 1,
    };
    const tmp = `${file}.switchboard.tmp`;
    fs.writeFileSync(tmp, JSON.stringify(cfg, null, 2));
    fs.renameSync(tmp, file); // atomic: never leave a half-written config
    log?.info('folder auto-trusted', { folder: key });
    return true;
  } catch (err) {
    // fail-open: the session just shows the trust dialog as normal
    log?.warn('auto-trust skipped', { folder, error: String(err) });
    return false;
  }
}

import { describe, it, expect, beforeEach, vi } from 'vitest';
import fs from 'fs';
import os from 'os';
import path from 'path';

let home: string;
vi.mock('os', async (orig) => {
  const actual = await orig<typeof import('os')>();
  return { ...actual, homedir: () => home };
});

import { ensureFolderTrusted, projectKey } from './trust';

beforeEach(() => {
  home = fs.mkdtempSync(path.join(os.tmpdir(), 'sb-trust-'));
});

function writeCfg(obj: unknown): void {
  fs.writeFileSync(path.join(home, '.claude.json'), JSON.stringify(obj));
}
function readCfg(): { projects: Record<string, Record<string, unknown>> } {
  return JSON.parse(fs.readFileSync(path.join(home, '.claude.json'), 'utf8'));
}

describe('projectKey', () => {
  it('uses forward slashes (how Claude Code keys projects)', () => {
    expect(projectKey('C:\\Games')).toBe('C:/Games');
    expect(projectKey('C:/Games/')).toBe('C:/Games');
  });
});

describe('ensureFolderTrusted', () => {
  it('sets the trust flag under the forward-slash key, merging other config', () => {
    writeCfg({ projects: { 'C:/Games': { allowedTools: ['Read'] } }, hasCompletedOnboarding: true });
    expect(ensureFolderTrusted('C:\\Games')).toBe(true);
    const cfg = readCfg();
    expect(cfg.projects['C:/Games'].hasTrustDialogAccepted).toBe(true);
    expect(cfg.projects['C:/Games'].allowedTools).toEqual(['Read']); // untouched
    expect((cfg as Record<string, unknown>).hasCompletedOnboarding).toBe(true); // untouched
  });

  it('creates the project entry when absent', () => {
    writeCfg({ projects: {} });
    ensureFolderTrusted('C:\\New\\Folder');
    expect(readCfg().projects['C:/New/Folder'].hasTrustDialogAccepted).toBe(true);
  });

  it('is a no-op when already trusted', () => {
    writeCfg({ projects: { 'C:/Games': { hasTrustDialogAccepted: true, projectOnboardingSeenCount: 5 } } });
    expect(ensureFolderTrusted('C:\\Games')).toBe(true);
    expect(readCfg().projects['C:/Games'].projectOnboardingSeenCount).toBe(5); // not reset
  });

  it('fails open (returns false, no throw) when the config is unreadable', () => {
    // no .claude.json written
    expect(ensureFolderTrusted('C:\\Games')).toBe(false);
  });
});

