// Fake provider for e2e tests (SWITCHBOARD_FAKE_PROVIDER=1). Spawns the OS
// shell in a real PTY instead of the claude CLI — a genuine interactive
// terminal we can type into and assert on, with no CLI login and no network,
// so UI tests are hermetic and CI-safe. Registered under the 'claude-code' id
// the UI uses, replacing the real adapter in test mode only.
import { ProviderAdapter, SpawnRecipe } from '../extensibility/contributions';

export const fakeAdapter: ProviderAdapter = {
  manifest: {
    id: 'claude-code',
    displayName: 'Fake (test)',
    version: '0.0.0',
    capabilities: ['sessions.spawn'],
  },
  buildSpawn(): SpawnRecipe {
    return {
      command: process.platform === 'win32' ? 'cmd.exe' : 'sh',
      args: [],
      env: {
        // S-01 landmines: never leak these into the hosted shell
        ELECTRON_RUN_AS_NODE: undefined,
        ELECTRON_NO_ATTACH_CONSOLE: undefined,
      },
    };
  },
};

// Bootstrap: the ONLY module allowed to import contributors directly — it
// populates the registry; everyone else resolves through it (§5.23).
import { registry } from './extensibility/registry';
import { claudeAdapter } from './providers/claude';
import { fakeAdapter } from './providers/fake';

export function registerBuiltinContributions(): void {
  // e2e tests swap the real CLI for a shell-in-a-PTY (hermetic, no login)
  if (process.env.SWITCHBOARD_FAKE_PROVIDER === '1') {
    registry.register('provider-adapter', fakeAdapter);
    return;
  }
  registry.register('provider-adapter', claudeAdapter);
}

import { defineConfig } from '@playwright/test';

// Electron e2e. App launches are heavy, so serialize (workers: 1) and don't
// parallelize. Each test gets its own isolated app instance + temp home.
export default defineConfig({
  testDir: './e2e',
  timeout: 60_000,
  expect: { timeout: 10_000 },
  fullyParallel: false,
  workers: 1,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 1 : 0,
  reporter: [['list']],
  use: { trace: 'retain-on-failure' },
});

// Launch the built Electron app under Playwright, fully isolated: a temp HOME
// so it never touches the real ~/.claude.json or workspace, the fake provider
// (shell-in-a-PTY, no claude login), and the S-01 env landmines scrubbed.
import { _electron as electron, ElectronApplication, Page } from '@playwright/test';
import path from 'path';
import fs from 'fs';
import os from 'os';

// electron's main export is the path to its binary when require()d in Node
// eslint-disable-next-line @typescript-eslint/no-require-imports
const electronPath = require('electron') as string;

const ROOT = path.resolve(__dirname, '..', '..');

export interface LaunchedApp {
  app: ElectronApplication;
  window: Page;
  home: string;
  cleanup: () => Promise<void>;
}

export interface LaunchOptions {
  /** auto-create one fake session in this folder at boot */
  seedFolder?: string;
  /** extra env for the main process */
  env?: Record<string, string>;
}

export async function launchApp(opts: LaunchOptions = {}): Promise<LaunchedApp> {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), 'sb-e2e-'));
  const appData = path.join(home, 'AppData', 'Roaming');
  const localAppData = path.join(home, 'AppData', 'Local');
  fs.mkdirSync(appData, { recursive: true });
  fs.mkdirSync(localAppData, { recursive: true });

  const env: Record<string, string> = { ...process.env } as Record<string, string>;
  delete env.ELECTRON_RUN_AS_NODE;
  delete env.ELECTRON_NO_ATTACH_CONSOLE;
  delete env.NoDefaultCurrentDirectoryInExePath;
  env.SWITCHBOARD_FAKE_PROVIDER = '1';
  // isolate every path the app derives from the profile
  env.HOME = home;
  env.USERPROFILE = home;
  env.APPDATA = appData;
  env.LOCALAPPDATA = localAppData;
  if (opts.seedFolder) env.SWITCHBOARD_SEED_SESSION = opts.seedFolder;
  Object.assign(env, opts.env);

  const app = await electron.launch({ executablePath: electronPath, args: [ROOT], cwd: ROOT, env });
  const window = await app.firstWindow();
  await window.waitForLoadState('domcontentloaded');

  return {
    app,
    window,
    home,
    cleanup: async () => {
      await app.close().catch(() => {});
      try {
        fs.rmSync(home, { recursive: true, force: true });
      } catch {
        /* best-effort */
      }
    },
  };
}

/** A throwaway folder to point a session at (git-repo optional). */
export function tempProjectFolder(): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'sb-e2e-proj-'));
  fs.writeFileSync(path.join(dir, 'README.md'), '# e2e\n');
  return dir;
}

