// Popout-layout persistence helpers (P2-E8-02). dockview serializes popout
// groups with their url + on-screen position, so the workspace layout already
// round-trips them — but two things must be fixed on restore:
//  1. the stored url carries the loopback server's port, which is RANDOM each
//     launch, so rewrite every popout url to the current origin;
//  2. if a popout's saved position is off every current display (monitor
//     unplugged), rescue it — null the position so dockview reopens it on/near
//     the main window instead of a monitor that no longer exists.

export interface Box {
  left: number;
  top: number;
  width: number;
  height: number;
}
export interface WorkArea {
  x: number;
  y: number;
  width: number;
  height: number;
}

interface PopoutGroup {
  url?: string;
  position?: Box | null;
  [k: string]: unknown;
}
interface Layout {
  popoutGroups?: PopoutGroup[];
  [k: string]: unknown;
}

/** At least a usable corner of the popout is visible on some display. */
export function boxOnAnyDisplay(box: Box, workAreas: WorkArea[]): boolean {
  return workAreas.some(
    (a) =>
      box.left < a.x + a.width - 80 &&
      box.left + box.width > a.x + 80 &&
      box.top < a.y + a.height - 40 &&
      box.top + box.height > a.y + 20
  );
}

/** Rewrite popout urls to the current origin and rescue off-display positions. */
export function sanitizePopoutLayout(layout: unknown, origin: string, workAreas: WorkArea[]): unknown {
  if (!layout || typeof layout !== 'object') return layout;
  const l = { ...(layout as Layout) };
  if (Array.isArray(l.popoutGroups)) {
    l.popoutGroups = l.popoutGroups.map((p) => {
      const np: PopoutGroup = { ...p };
      if (typeof np.url === 'string') np.url = `${origin}/popout.html`;
      if (np.position && workAreas.length > 0 && !boxOnAnyDisplay(np.position, workAreas)) {
        np.position = null; // rescue onto the main window
      }
      return np;
    });
  }
  return l;
}

import { describe, it, expect } from 'vitest';
import { sanitizePopoutLayout, boxOnAnyDisplay } from './layout';

const primary = { x: 0, y: 0, width: 1920, height: 1040 };
const second = { x: 1920, y: 0, width: 1920, height: 1040 };

describe('boxOnAnyDisplay', () => {
  it('true when a corner is visible, false when fully off-screen', () => {
    expect(boxOnAnyDisplay({ left: 100, top: 100, width: 800, height: 600 }, [primary])).toBe(true);
    expect(boxOnAnyDisplay({ left: 2200, top: 100, width: 800, height: 600 }, [primary])).toBe(false);
    expect(boxOnAnyDisplay({ left: 2200, top: 100, width: 800, height: 600 }, [primary, second])).toBe(true);
  });
});

describe('sanitizePopoutLayout', () => {
  const origin = 'http://127.0.0.1:55555';

  it('rewrites popout urls to the current origin (port changes each launch)', () => {
    const layout = {
      popoutGroups: [{ url: 'http://127.0.0.1:40000/popout.html', position: { left: 100, top: 100, width: 800, height: 600 } }],
    };
    const out = sanitizePopoutLayout(layout, origin, [primary]) as typeof layout;
    expect(out.popoutGroups[0].url).toBe('http://127.0.0.1:55555/popout.html');
  });

  it('rescues an off-display popout position to null', () => {
    const layout = {
      popoutGroups: [{ url: 'x', position: { left: 3000, top: 100, width: 800, height: 600 } }],
    };
    // second monitor gone -> position rescued
    const out = sanitizePopoutLayout(layout, origin, [primary]) as typeof layout;
    expect(out.popoutGroups[0].position).toBeNull();
  });

  it('keeps an on-display popout position', () => {
    const layout = {
      popoutGroups: [{ url: 'x', position: { left: 2100, top: 100, width: 800, height: 600 } }],
    };
    const out = sanitizePopoutLayout(layout, origin, [primary, second]) as typeof layout;
    expect(out.popoutGroups[0].position).toEqual({ left: 2100, top: 100, width: 800, height: 600 });
  });

  it('no-ops on layouts without popouts / on garbage', () => {
    expect(sanitizePopoutLayout({ panels: {} }, origin, [primary])).toEqual({ panels: {} });
    expect(sanitizePopoutLayout(null, origin, [primary])).toBeNull();
  });
});

