10	export function TerminalPane(props: { sessionId: string; visible: boolean }): React.JSX.Element {
11	  const hostRef = useRef<HTMLDivElement | null>(null);
12	  const termRef = useRef<Terminal | null>(null);
13	  const fitRef = useRef<FitAddon | null>(null);
14	  const visibleRef = useRef(props.visible);
15	  visibleRef.current = props.visible;
16	
17	  // terminal lifecycle: created once per mounted pane
18	  useEffect(() => {
19	    const term = new Terminal({
20	      scrollback: 5000, // S-07 verdict
21	      // concrete stack: xterm can't resolve CSS custom properties
22	      fontFamily: "'IBM Plex Mono', Consolas, 'Cascadia Mono', monospace",
23	      fontSize: 13,
24	    });
25	    const fit = new FitAddon();
26	    term.loadAddon(fit);
27	    term.open(hostRef.current!);
28	    termRef.current = term;
29	    fitRef.current = fit;
30	
31	    term.onData((d) => window.switchboard.pty.input(props.sessionId, d));
32	
33	    const ro = new ResizeObserver(() => {
34	      // hidden panes collapse to a 2x1 min; resizing the PTY there makes the
35	      // real CLI reflow its TUI into the ring buffer as garbage (S-07). Only
36	      // resize while visible and above the fit-addon minimum.
37	      if (!termRef.current || !visibleRef.current) return;
38	      fit.fit();
39	      if (term.cols > 2 && term.rows > 1) {
40	        window.switchboard.pty.resize(props.sessionId, term.cols, term.rows);
41	      }
42	    });
43	    ro.observe(hostRef.current!);
44	
45	    return () => {
46	      ro.disconnect();
47	      window.switchboard.pty.detach(props.sessionId);
48	      term.dispose();
49	      termRef.current = null;
50	    };
51	  }, [props.sessionId]);
52	
53	  // visibility drives attach/detach (hidden panes are ingest-only in main)
54	  useEffect(() => {
55	    const term = termRef.current;
56	    if (!term) return;
57	    if (!props.visible) {
58	      window.switchboard.pty.detach(props.sessionId);
59	      return;
60	    }
61	    let off: (() => void) | null = null;
62	    let cancelled = false;
63	    void window.switchboard.pty.attach(props.sessionId).then((snapshot) => {
64	      if (cancelled) return;
65	      term.reset();
66	      if (snapshot) term.write(snapshot);
67	      off = window.switchboard.pty.onData(props.sessionId, (d) => term.write(d));
68	      fitRef.current?.fit();
69	      window.switchboard.pty.resize(props.sessionId, term.cols, term.rows);
70	    });
71	    return () => {
72	      cancelled = true;
73	      off?.();
74	      window.switchboard.pty.detach(props.sessionId);
75	    };
76	  }, [props.sessionId, props.visible]);
