test.describe('diag', () => {
  let a: LaunchedApp;
  test.afterEach(async () => a?.cleanup());

  test('popout close DOM state', async () => {
    const folder = tempProjectFolder();
    const name = path.basename(folder);
    a = await launchApp({ seedFolder: folder });
    const { app, window } = a;
    await expect(window.getByText(name).first()).toBeVisible({ timeout: 25_000 });

    await window.getByTitle('Pop out into its own window').click();
    await expect.poll(() => app.windows().length, { timeout: 15_000 }).toBe(2);
    const popout = app.windows().find((w) => w !== window)!;
    await expect(popout.locator('.xterm-screen').first()).toBeVisible({ timeout: 15_000 });

    await popout.close();
    await expect.poll(() => app.windows().length, { timeout: 15_000 }).toBe(1);
    await window.waitForTimeout(1500);

    const state = await window.evaluate(() => {
      const xterms = document.querySelectorAll('.xterm');
      const screens = document.querySelectorAll('.xterm-screen');
      const cards = document.querySelectorAll('[class*="dv-"]').length;
      const first = screens[0] as HTMLElement | undefined;
      return {
        xtermCount: xterms.length,
        screenCount: screens.length,
        dvNodes: cards,
        firstScreenRect: first ? first.getBoundingClientRect() : null,
        bodyText: document.body.innerText.slice(0, 300),
      };
    });
    console.log('DIAG_STATE', JSON.stringify(state, null, 2));
  });
});

