        raf.push(requestAnimationFrame(() => tryFit(attemptsLeft - 1)));
      }
    };
    tryFit(10);
  });
  return () => {
    cancelled = true;
    raf.forEach((h) => cancelAnimationFrame(h));
    off?.();
    window.switchboard.pty.detach(props.sessionId);
  };
}, [props.sessionId, props.visible]);

