387	  // Add a NEW card. It gets a stable id and spawns its session lazily when it
388	  // becomes visible (which, as the newly-active tab, is immediately).
389	  const addSessionCard = useCallback(async (folder: string) => {
390	    const api = apiRef.current;
391	    if (!api) return;
392	    const title = folder.replace(/[\\/]+$/, '').split(/[\\/]/).pop() ?? folder;
393	    const cardId = crypto.randomUUID();
394	    // A new session must land in the MAIN window, never as a tab inside whatever
395	    // popout happens to be active. dockview's addPanel defaults to the active
396	    // group — which becomes the popout once a card is torn off — so pin it to a
397	    // main-grid group explicitly (E8-04). If none exists yet, plain addPanel
398	    // seeds the main root.
399	    const mainGroup = api.groups.find((g) => g.api.location.type === 'grid');
400	    api.addPanel({
401	      id: `session-${cardId}`,
402	      component: 'sessionCard',
403	      title,
404	      params: { cardId, folder, title } satisfies CardParams,
405	      ...(mainGroup ? { position: { referenceGroup: mainGroup } } : {}),
406	    });
407	  }, []);
408	
409	  React.useEffect(() => {
410	    if (!props.controller) return;
411	    props.controller.current = {
412	      addSessionCard,
413	      focusSession: (liveId) => {
414	        apiRef.current?.getPanel(`session-${cardIdForLive(liveId)}`)?.focus();
415	      },
416	      openDiff: (liveId, folder, title) => {
417	        const api = apiRef.current;
418	        if (!api) return;
419	        const cardId = cardIdForLive(liveId);
420	        const existing = api.getPanel(`diff-${cardId}`);
421	        if (existing) return existing.focus();
422	        api.addPanel({
423	          id: `diff-${cardId}`,
424	          component: 'diffPane',
425	          title: t('diff.tabTitle', { title }),
426	          params: { folder, theme: props.theme },
427	        });
428	      },
429	    };
430	    // eslint's exhaustive-deps plugin isn't installed; deps kept accurate by hand
431	  }, [props.controller, addSessionCard, props.theme, t]);
