455	      });
456	      // E8 diagnostics: surface popout success/failure
457	      api.onDidOpenPopoutWindowFail?.(() => console.error('[popout] onDidOpenPopoutWindowFail'));
458	      api.onDidAddPopoutGroup?.(() => console.log('[popout] onDidAddPopoutGroup (opened OK)'));
459	      // window teardown must not be mistaken for the user closing cards
460	      window.addEventListener('beforeunload', () => {
461	        tearingDown = true;
462	      });
463	      // closing a card (tab X or the overlay) forgets it — it will NOT come
464	      // back next launch. Quitting keeps the record so sessions DO come back,
465	      // so we skip this during teardown (belt-and-suspenders vs Dockview
466	      // disposal ever firing removes).
467	      api.onDidRemovePanel((panel) => {
468	        if (tearingDown) return;
