470	        if (!m) return;
471	        forgetCardLiveIds(m[1]);
472	        void window.switchboard.sessions.closeCard(m[1]);
473	      });
474	
475	      const saved = await window.switchboard.workspace.getLayout();
476	      if (saved) {
